insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 'Nice to meet you', 'Verb to be & introductions', 'Primeiros passos para se apresentar com confiança.', 'ingles', 1, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('cc6b4330-cf11-5006-8673-e4dc429f96c8', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 0, 'Dica', '', 'dica', '{"texto": "Use am com I, is com he/she/it e are com you/we/they. Na conversa, o mais natural é contrair: I''m, you''re, she''s. Para perguntar, inverta a ordem: Are you from Brazil?"}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('571a3587-b7a9-50d3-9f5f-e7813e606c97', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 1, 'Listening: First day at the office', 'Ouça o diálogo e responda.', 'audio', '{"roteiro": "LUCAS: Hi! Are you the new designer?\nEMMA: Yes, I am. I''m Emma. Nice to meet you.\nLUCAS: Nice to meet you too, Emma. I''m Lucas. I''m the office manager.\nEMMA: Where are you from, Lucas?\nLUCAS: I''m from Brazil, from Curitiba. And you?\nEMMA: I''m from Canada. I''m from Toronto.\nLUCAS: Welcome to the team! Your desk is next to the window.\nEMMA: Great, thank you. Is the meeting room on this floor?\nLUCAS: No, it isn''t. It''s on the second floor.", "generos": {"LUCAS": "masculina", "EMMA": "feminina"}, "vozes": {"LUCAS": "Puck", "EMMA": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-01-nice-to-meet-you.mp3", "audio_assinatura": "EMMA=Kore;LUCAS=Puck|LUCAS: Hi! Are you the new designer?\nEMMA: Yes, I am. I''m Emma. Nice to meet you.\nLUCAS: Nice to meet you too, Emma. I''m Lucas. I''m the office manager.\nEMMA: Where are you from, Lucas?\nLUCAS: I''m from Brazil, from Curitiba. And you?\nEMMA: I''m from Canada. I''m from Toronto.\nLUCAS: Welcome to the team! Your desk is next to the window.\nEMMA: Great, thank you. Is the meeting room on this floor?\nLUCAS: No, it isn''t. It''s on the second floor.", "duracao": 51.8}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('52cac344-3a57-5fcb-8abc-befcb9681e30', '571a3587-b7a9-50d3-9f5f-e7813e606c97', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 0, 'multipla_escolha', 'listening', 'What is Emma''s job?', '{"opcoes": ["Designer", "Office manager", "Teacher"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('52cac344-3a57-5fcb-8abc-befcb9681e30', '{"correta": 0}'::jsonb, 'Lucas pergunta "Are you the new designer?" e ela confirma.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('790ca307-6a37-5384-904d-c8ed9d277578', '571a3587-b7a9-50d3-9f5f-e7813e606c97', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 1, 'multipla_escolha', 'listening', 'Where is Lucas from?', '{"opcoes": ["Canada", "Brazil", "Portugal"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('790ca307-6a37-5384-904d-c8ed9d277578', '{"correta": 1}'::jsonb, 'Ele diz que é de Curitiba, no Brasil.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e4258ee3-d9a2-5958-bcca-24d5c5acf30c', '571a3587-b7a9-50d3-9f5f-e7813e606c97', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 2, 'verdadeiro_falso', 'listening', 'Emma is from Toronto.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e4258ee3-d9a2-5958-bcca-24d5c5acf30c', '{"valor": true}'::jsonb, 'Ela diz: I''m from Toronto.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('9834081a-387f-5083-bc63-1df3b19261c9', '571a3587-b7a9-50d3-9f5f-e7813e606c97', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 3, 'verdadeiro_falso', 'listening', 'The meeting room is on the first floor.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('9834081a-387f-5083-bc63-1df3b19261c9', '{"valor": false}'::jsonb, 'A sala de reunião fica no segundo andar (second floor).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('218a690b-01c4-5cb3-8d93-3867970de5eb', '571a3587-b7a9-50d3-9f5f-e7813e606c97', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 4, 'multipla_escolha', 'listening', 'Where is Emma''s desk?', '{"opcoes": ["Next to the door", "In the meeting room", "Next to the window"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('218a690b-01c4-5cb3-8d93-3867970de5eb', '{"correta": 2}'::jsonb, 'Lucas diz: your desk is next to the window.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 2, 'Am, is ou are?', 'Complete as frases com a forma certa do verbo to be.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('64d6f6e9-7651-5e5a-bece-91c8178e4645', 'b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 0, 'lacuna', 'grammar', 'I ___ a student and my sister ___ a nurse.', '{"banco": ["am", "is", "are"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('64d6f6e9-7651-5e5a-bece-91c8178e4645', '{"lacunas": [["am"], ["is"]], "ignorar_acentos": false}'::jsonb, 'I combina com am; my sister (she) combina com is.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c6473ac4-9aa9-5053-a256-6d6567d5e56c', 'b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 1, 'lacuna', 'grammar', '___ you from São Paulo?', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c6473ac4-9aa9-5053-a256-6d6567d5e56c', '{"lacunas": [["Are"]], "ignorar_acentos": false}'::jsonb, 'Na pergunta, o verbo vem antes do sujeito: Are you...?');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('61f1dade-d142-5ef5-9ff5-599d009184b8', 'b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 2, 'lacuna_opcoes', 'grammar', 'They ___ at work right now.', '{"opcoes": [["is", "are", "am"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('61f1dade-d142-5ef5-9ff5-599d009184b8', '{"lacunas": [1]}'::jsonb, 'They (eles) usa are.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('80668f80-cf81-5680-93f9-14e042ee3f6e', 'b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 3, 'multipla_escolha', 'grammar', 'Choose the correct short form of "She is my boss".', '{"opcoes": ["Shes my boss.", "She''s my boss.", "She''is my boss."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('80668f80-cf81-5680-93f9-14e042ee3f6e', '{"correta": 1}'::jsonb, 'O apóstrofo substitui o i de is: she''s.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('8b3e053c-6e16-56dc-8267-185f0299d228', 'b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 4, 'resposta_curta', 'writing', 'Escreva a frase na negativa, usando contração: He is here.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('8b3e053c-6e16-56dc-8267-185f0299d228', '{"aceitas": ["He isn''t here", "He''s not here"], "ignorar_acentos": false}'::jsonb, 'Is not vira isn''t (ou he''s not).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('be8b88ea-098e-53fa-bd10-f1715168867c', 'b67a22bb-2bd1-50cc-adf6-fd792a9e77e9', '4ba690c0-6dca-5f6e-86cf-9e0644f934eb', 5, 'multipla_escolha', 'vocabulary', '"What''s your name?" Which answer is correct?', '{"opcoes": ["I''m from Paula.", "My name is Paula.", "I have Paula."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('be8b88ea-098e-53fa-bd10-f1715168867c', '{"correta": 1}'::jsonb, 'Para dizer o nome: My name is... ou I''m...');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('e81c1da0-791f-52db-81d6-9b4d53214ae8', 'At the restaurant', 'Would like, some & any', 'Peça, pergunte e pague como um local.', 'ingles', 2, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('9298898a-eea1-5888-bfc8-7d3741a9d279', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 0, 'Dica', '', 'dica', '{"texto": "Use would like (''d like) para pedir com educação: I''d like a salad, please. Some aparece em frases afirmativas e em ofertas (Would you like some water?); any, em perguntas e negativas (Do you have any vegetarian dishes?)."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('18fcaf75-aa55-5ccb-a404-cd815252e1eb', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 1, 'Listening: A table for one', 'Ouça o pedido de Sophie e responda.', 'audio', '{"roteiro": "WAITER: Good evening. Are you ready to order?\nSOPHIE: Yes, I think so. Do you have any vegetarian dishes?\nWAITER: Yes, we do. The mushroom risotto is very popular, and we also have a vegetable curry.\nSOPHIE: I''d like the risotto, please.\nWAITER: Would you like a starter?\nSOPHIE: No, thanks. But I''d like some sparkling water.\nWAITER: A small or a large bottle?\nSOPHIE: Small, please. Oh, and is service included?\nWAITER: No, it isn''t. But you can pay by card at the table.\nSOPHIE: Perfect. Thank you!", "generos": {"WAITER": "masculina", "SOPHIE": "feminina"}, "vozes": {"WAITER": "Puck", "SOPHIE": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-02-at-the-restaurant.mp3", "audio_assinatura": "SOPHIE=Kore;WAITER=Puck|WAITER: Good evening. Are you ready to order?\nSOPHIE: Yes, I think so. Do you have any vegetarian dishes?\nWAITER: Yes, we do. The mushroom risotto is very popular, and we also have a vegetable curry.\nSOPHIE: I''d like the risotto, please.\nWAITER: Would you like a starter?\nSOPHIE: No, thanks. But I''d like some sparkling water.\nWAITER: A small or a large bottle?\nSOPHIE: Small, please. Oh, and is service included?\nWAITER: No, it isn''t. But you can pay by card at the table.\nSOPHIE: Perfect. Thank you!", "duracao": 52.4}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('39df8be4-41c0-5cc0-bbda-087c02c232c9', '18fcaf75-aa55-5ccb-a404-cd815252e1eb', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 0, 'multipla_escolha', 'listening', 'What does Sophie order?', '{"opcoes": ["The vegetable curry", "The mushroom risotto", "A starter"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('39df8be4-41c0-5cc0-bbda-087c02c232c9', '{"correta": 1}'::jsonb, 'Ela diz: I''d like the risotto, please.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('1433d24e-c918-5f76-b8f2-3c174e566a87', '18fcaf75-aa55-5ccb-a404-cd815252e1eb', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 1, 'verdadeiro_falso', 'listening', 'Sophie orders a starter too.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('1433d24e-c918-5f76-b8f2-3c174e566a87', '{"valor": false}'::jsonb, 'Ela responde "No, thanks" quando o garçom oferece uma entrada.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c9d1ab5b-2d9e-5e95-a3c8-177c4c6e9fa1', '18fcaf75-aa55-5ccb-a404-cd815252e1eb', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 2, 'multipla_escolha', 'listening', 'What does she want to drink?', '{"opcoes": ["Still water", "Orange juice", "Sparkling water"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c9d1ab5b-2d9e-5e95-a3c8-177c4c6e9fa1', '{"correta": 2}'::jsonb, 'Ela pede some sparkling water (água com gás).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('a481ab39-679f-5a37-a2ae-24e99fbccddf', '18fcaf75-aa55-5ccb-a404-cd815252e1eb', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 3, 'multipla_escolha', 'listening', 'What size is the bottle?', '{"opcoes": ["Small", "Large", "Medium"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('a481ab39-679f-5a37-a2ae-24e99fbccddf', '{"correta": 0}'::jsonb, 'Ela escolhe a garrafa pequena: Small, please.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('34bd08eb-a9cb-5727-a3d9-0366d004db93', '18fcaf75-aa55-5ccb-a404-cd815252e1eb', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 4, 'verdadeiro_falso', 'listening', 'Service is included in the bill.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('34bd08eb-a9cb-5727-a3d9-0366d004db93', '{"valor": false}'::jsonb, 'O garçom diz: No, it isn''t.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 2, 'Some, any ou would like?', 'Complete ou escolha a melhor opção.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2ba17ee7-fb7a-5d98-8334-dcdf6502d32d', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 0, 'lacuna_opcoes', 'grammar', 'Do you have ___ tables free tonight?', '{"opcoes": [["some", "any"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2ba17ee7-fb7a-5d98-8334-dcdf6502d32d', '{"lacunas": [1]}'::jsonb, 'Em perguntas comuns usamos any.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('ed9f4b32-05e7-5217-b8ef-0bbf3d310d91', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 1, 'lacuna_opcoes', 'grammar', 'Would you like ___ more bread?', '{"opcoes": [["some", "any"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('ed9f4b32-05e7-5217-b8ef-0bbf3d310d91', '{"lacunas": [0]}'::jsonb, 'Em ofertas usamos some, mesmo sendo pergunta.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('6b1cfbc5-7769-5854-9f93-0ee94282b0f4', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 2, 'lacuna', 'grammar', 'We don''t have ___ milk, sorry.', '{"banco": ["some", "any"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('6b1cfbc5-7769-5854-9f93-0ee94282b0f4', '{"lacunas": [["any"]], "ignorar_acentos": false}'::jsonb, 'Em frases negativas usamos any.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('605322f8-a0b5-5975-8171-1c140fe6a849', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 3, 'lacuna', 'grammar', '___ you like a dessert?', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('605322f8-a0b5-5975-8171-1c140fe6a849', '{"lacunas": [["Would"]], "ignorar_acentos": false}'::jsonb, 'Would you like...? é a forma educada de oferecer.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2faad8d3-57a0-5a82-8237-8a7bec652bdd', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 4, 'multipla_escolha', 'vocabulary', 'Which is the most polite way to order?', '{"opcoes": ["I want a coffee.", "Give me a coffee.", "I''d like a coffee, please."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2faad8d3-57a0-5a82-8237-8a7bec652bdd', '{"correta": 2}'::jsonb, 'I''d like... please soa educado; I want soa direto demais.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c78e7dbb-b49e-5418-b059-508723ffe4f3', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 5, 'resposta_curta', 'writing', 'Como se pede a conta em inglês? (frase curta)', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c78e7dbb-b49e-5418-b059-508723ffe4f3', '{"aceitas": ["The bill, please", "Can I have the bill, please", "Could I have the bill, please", "Can we have the bill, please", "Could we have the bill, please", "The check, please", "Can I have the check, please", "Could I have the check, please", "Can we have the check, please", "Could we have the check, please", "The bill please", "Can I have the bill please", "Could I have the bill please", "Can we have the bill please", "Could we have the bill please", "The check please", "Can I have the check please", "Could I have the check please", "Can we have the check please", "Could we have the check please"], "ignorar_acentos": false}'::jsonb, 'Bill é mais britânico; check, mais americano.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('db416c2b-9255-5788-bb03-328beaaee100', '1c1e94da-49ef-5886-9644-1b81e13c92a7', 'e81c1da0-791f-52db-81d6-9b4d53214ae8', 6, 'completar_letras', 'vocabulary', 'Des_ert (sobremesa)', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('db416c2b-9255-5788-bb03-328beaaee100', '{"lacunas": [["s"]], "ignorar_acentos": false}'::jsonb, 'Dessert (sobremesa) tem dois s; desert (deserto) tem um só.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('e3545162-dd47-5a62-b054-4d97811fb4d8', 'Travel plans', 'Going to vs will', 'Planos, decisões e previsões para a sua próxima viagem.', 'ingles', 3, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('df3f20a6-f884-5718-b138-cee2b18dd744', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 0, 'Dica', '', 'dica', '{"texto": "Going to = plano já decidido antes de falar (I''m going to visit Lisbon in May) ou previsão com evidência (Look at those clouds! It''s going to rain). Will = decisão na hora, promessa ou oferta (I''ll help you with your bag)."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('f775a8b6-eeca-5cad-a501-09762f6939c1', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 1, 'Listening: At the check-in desk', 'Ouça o diálogo no aeroporto e responda.', 'audio', '{"roteiro": "AGENT: Good morning. Where are you flying today?\nDANIEL: To Lisbon. I''m going to spend a week there for a conference.\nAGENT: Can I see your passport, please?\nDANIEL: Sure, here you are.\nAGENT: Thank you. Are you going to check in this suitcase?\nDANIEL: Yes, just this one. The backpack is my hand luggage.\nAGENT: Your suitcase is twenty-four kilos. The limit is twenty-three, I''m afraid.\nDANIEL: Oh no. OK, I''ll take my laptop out and put it in my backpack.\nAGENT: Great, that works. Here''s your boarding pass. Boarding starts at ten fifteen, at gate twelve.\nDANIEL: Thanks. Is there a café near the gate?\nAGENT: Yes, there''s one right in front of it. Have a good flight!", "generos": {"AGENT": "feminina", "DANIEL": "masculina"}, "vozes": {"AGENT": "Kore", "DANIEL": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-03-travel-plans.mp3", "audio_assinatura": "AGENT=Kore;DANIEL=Puck|AGENT: Good morning. Where are you flying today?\nDANIEL: To Lisbon. I''m going to spend a week there for a conference.\nAGENT: Can I see your passport, please?\nDANIEL: Sure, here you are.\nAGENT: Thank you. Are you going to check in this suitcase?\nDANIEL: Yes, just this one. The backpack is my hand luggage.\nAGENT: Your suitcase is twenty-four kilos. The limit is twenty-three, I''m afraid.\nDANIEL: Oh no. OK, I''ll take my laptop out and put it in my backpack.\nAGENT: Great, that works. Here''s your boarding pass. Boarding starts at ten fifteen, at gate twelve.\nDANIEL: Thanks. Is there a café near the gate?\nAGENT: Yes, there''s one right in front of it. Have a good flight!", "duracao": 57.5}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c01dd7e7-0fd5-5a65-a683-7df17442ac2c', 'f775a8b6-eeca-5cad-a501-09762f6939c1', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 0, 'multipla_escolha', 'listening', 'Why is Daniel travelling to Lisbon?', '{"opcoes": ["For a holiday", "For a conference", "To visit family"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c01dd7e7-0fd5-5a65-a683-7df17442ac2c', '{"correta": 1}'::jsonb, 'Ele vai a Lisboa para uma conferência.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('3a989bf7-7738-5147-8492-4cbe469c6d98', 'f775a8b6-eeca-5cad-a501-09762f6939c1', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 1, 'multipla_escolha', 'listening', 'How long is he going to stay?', '{"opcoes": ["A weekend", "A month", "A week"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('3a989bf7-7738-5147-8492-4cbe469c6d98', '{"correta": 2}'::jsonb, 'Ele diz: I''m going to spend a week there.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e3079f4c-0774-52f9-9b29-d5f0227f5394', 'f775a8b6-eeca-5cad-a501-09762f6939c1', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 2, 'verdadeiro_falso', 'listening', 'His suitcase is under the weight limit.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e3079f4c-0774-52f9-9b29-d5f0227f5394', '{"valor": false}'::jsonb, 'A mala tem 24 kg e o limite é de 23 kg.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('d3e422af-e9bf-5a6c-afd6-8f090d5fe554', 'f775a8b6-eeca-5cad-a501-09762f6939c1', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 3, 'multipla_escolha', 'listening', 'What does Daniel decide to do?', '{"opcoes": ["Pay an extra fee", "Take his laptop out of the suitcase", "Leave his backpack at home"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('d3e422af-e9bf-5a6c-afd6-8f090d5fe554', '{"correta": 1}'::jsonb, 'Decisão na hora: I''ll take my laptop out.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('62e6e652-af71-5f7f-9eef-373c1883353c', 'f775a8b6-eeca-5cad-a501-09762f6939c1', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 4, 'multipla_escolha', 'listening', 'When does boarding start?', '{"opcoes": ["At 10:15", "At 10:50", "At 12:00"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('62e6e652-af71-5f7f-9eef-373c1883353c', '{"correta": 0}'::jsonb, 'Boarding starts at ten fifteen; 12 é o número do portão.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 2, 'Going to ou will?', 'Pense: é plano, previsão com evidência ou decisão na hora?', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7364c1a2-744a-58d8-afa0-988d641d1fe3', 'c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 0, 'lacuna_opcoes', 'grammar', 'Look at those dark clouds! It ___ rain.', '{"opcoes": [["is going to", "will"]]}'::jsonb);
