insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('5c126e22-44ed-5640-834f-ac4f5c27f467', 'c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 1, 'lacuna_opcoes', 'grammar', 'A: The phone is ringing. B: I ___ get it!', '{"opcoes": [["''m going to", "''ll"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('5c126e22-44ed-5640-834f-ac4f5c27f467', '{"lacunas": [1]}'::jsonb, 'Decisão tomada na hora de falar: will (''ll).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('0eb3a220-7fc3-5911-ae74-3bd6d7913e81', 'c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 2, 'lacuna', 'grammar', 'We ___ visit my grandparents next weekend. We bought the tickets yesterday.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('0eb3a220-7fc3-5911-ae74-3bd6d7913e81', '{"lacunas": [["are going to"]], "ignorar_acentos": false}'::jsonb, 'Plano já decidido (as passagens já foram compradas): going to.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('a31b6bcc-1d24-5039-bcab-f03c10e883c2', 'c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 3, 'multipla_escolha', 'grammar', 'Which sentence is a promise?', '{"opcoes": ["I''m going to call you tonight.", "I''ll call you tonight, I promise.", "I call you tonight."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('a31b6bcc-1d24-5039-bcab-f03c10e883c2', '{"correta": 1}'::jsonb, 'Promessas usam will.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7e43a5a9-42b3-52ac-ada7-254655f9ae71', 'c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 4, 'resposta_curta', 'writing', 'Ofereça ajuda em inglês: "Eu vou te ajudar com a mala."', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('7e43a5a9-42b3-52ac-ada7-254655f9ae71', '{"aceitas": ["I''ll help you with the suitcase", "I will help you with the suitcase", "I''ll help you with your suitcase", "I will help you with your suitcase", "I''ll help you with the bag", "I will help you with the bag", "I''ll help you with your bag", "I will help you with your bag"], "ignorar_acentos": false}'::jsonb, 'Oferta feita na hora: will (I''ll).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('d8758888-6b05-525d-9d26-de443be44913', 'c710f873-0645-568a-b110-95055de23d52', 'e3545162-dd47-5a62-b054-4d97811fb4d8', 5, 'verdadeiro_falso', 'vocabulary', '"Hand luggage" is the bag you take with you onto the plane.', '{}'::jsonb);
