insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('8ea30ab2-a016-534c-8871-0e2a9c154658', 'The job interview', 'Present perfect vs past simple', 'Fale da sua experiência sem travar na entrevista.', 'ingles', 4, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('9bb4b58c-ec3a-5849-958b-522dbfb67ea0', '8ea30ab2-a016-534c-8871-0e2a9c154658', 0, 'Dica', '', 'dica', '{"texto": "Past simple = ação terminada com tempo definido (I joined the company in 2021). Present perfect = experiência ou ação com efeito no presente, sem tempo definido (I''ve worked with international clients). Com for e since, o present perfect liga o passado ao agora."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('835b38ed-4ab3-52cf-b155-a5ade2cbe73e', '8ea30ab2-a016-534c-8871-0e2a9c154658', 1, 'Listening: Interview for a project manager', 'Ouça a entrevista e responda.', 'audio', '{"roteiro": "INTERVIEWER: So, Rafael, tell me a bit about your experience.\nRAFAEL: Sure. I''ve worked in project management for about seven years. I started at a small marketing agency in 2019, and then I moved to a tech company in 2022.\nINTERVIEWER: And what have you done there?\nRAFAEL: I''ve led three major product launches. The last one was an app for a bank, and we delivered it two weeks ahead of schedule.\nINTERVIEWER: Impressive. Have you ever managed a team abroad?\nRAFAEL: Yes, I have. Last year I coordinated developers in Portugal and India. The time difference was hard at first, but we created a simple routine with short daily calls.\nINTERVIEWER: And why do you want to leave your current job?\nRAFAEL: I''ve learned a lot there, but I''m looking for bigger international projects.", "generos": {"INTERVIEWER": "feminina", "RAFAEL": "masculina"}, "vozes": {"INTERVIEWER": "Kore", "RAFAEL": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-04-the-job-interview.mp3", "audio_assinatura": "INTERVIEWER=Kore;RAFAEL=Puck|INTERVIEWER: So, Rafael, tell me a bit about your experience.\nRAFAEL: Sure. I''ve worked in project management for about seven years. I started at a small marketing agency in 2019, and then I moved to a tech company in 2022.\nINTERVIEWER: And what have you done there?\nRAFAEL: I''ve led three major product launches. The last one was an app for a bank, and we delivered it two weeks ahead of schedule.\nINTERVIEWER: Impressive. Have you ever managed a team abroad?\nRAFAEL: Yes, I have. Last year I coordinated developers in Portugal and India. The time difference was hard at first, but we created a simple routine with short daily calls.\nINTERVIEWER: And why do you want to leave your current job?\nRAFAEL: I''ve learned a lot there, but I''m looking for bigger international projects.", "duracao": 57.8}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('4f372390-b291-5ed5-b058-045ddaf6632d', '835b38ed-4ab3-52cf-b155-a5ade2cbe73e', '8ea30ab2-a016-534c-8871-0e2a9c154658', 0, 'multipla_escolha', 'listening', 'How long has Rafael worked in project management?', '{"opcoes": ["About three years", "About seven years", "About ten years"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('4f372390-b291-5ed5-b058-045ddaf6632d', '{"correta": 1}'::jsonb, 'Ele diz: for about seven years.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('9704b9d3-9991-561a-85d4-76bf1c7b191b', '835b38ed-4ab3-52cf-b155-a5ade2cbe73e', '8ea30ab2-a016-534c-8871-0e2a9c154658', 1, 'multipla_escolha', 'listening', 'When did he move to a tech company?', '{"opcoes": ["In 2019", "Last year", "In 2022"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('9704b9d3-9991-561a-85d4-76bf1c7b191b', '{"correta": 2}'::jsonb, 'Ele começou na agência em 2019 e mudou em 2022.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('ca204db0-b529-59c8-a46f-8d27eae4c7ca', '835b38ed-4ab3-52cf-b155-a5ade2cbe73e', '8ea30ab2-a016-534c-8871-0e2a9c154658', 2, 'verdadeiro_falso', 'listening', 'The bank app was delivered late.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('ca204db0-b529-59c8-a46f-8d27eae4c7ca', '{"valor": false}'::jsonb, 'Foi entregue duas semanas antes do prazo (ahead of schedule).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e2459589-fb1e-584a-b01d-bf90e1ac7341', '835b38ed-4ab3-52cf-b155-a5ade2cbe73e', '8ea30ab2-a016-534c-8871-0e2a9c154658', 3, 'multipla_escolha', 'listening', 'What helped the international team?', '{"opcoes": ["Weekly reports", "Short daily calls", "Working the same hours"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e2459589-fb1e-584a-b01d-bf90e1ac7341', '{"correta": 1}'::jsonb, 'Eles criaram uma rotina com chamadas diárias curtas.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('745743a4-796e-5f09-a2e3-8fb12a4c74a1', '835b38ed-4ab3-52cf-b155-a5ade2cbe73e', '8ea30ab2-a016-534c-8871-0e2a9c154658', 4, 'verdadeiro_falso', 'listening', 'Rafael wants to leave because he is unhappy with his manager.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('745743a4-796e-5f09-a2e3-8fb12a4c74a1', '{"valor": false}'::jsonb, 'Ele quer projetos internacionais maiores; não fala mal do chefe.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 2, 'Present perfect ou past simple?', 'Repare se há um tempo definido no passado.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('747e34af-4d6b-53d2-a72b-cb2111a4c492', '396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 0, 'lacuna_opcoes', 'grammar', 'I ___ at a bank from 2018 to 2021.', '{"opcoes": [["worked", "have worked"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('747e34af-4d6b-53d2-a72b-cb2111a4c492', '{"lacunas": [0]}'::jsonb, 'Período terminado e definido: past simple.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2c0a817d-821e-54fc-b9fd-60b3fa6f602e', '396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 1, 'lacuna_opcoes', 'grammar', 'She ___ three books so far.', '{"opcoes": [["wrote", "has written"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2c0a817d-821e-54fc-b9fd-60b3fa6f602e', '{"lacunas": [1]}'::jsonb, 'So far (até agora) liga ao presente: present perfect.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('9e1253e4-1ff2-58d8-ab52-80d5a1778829', '396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 2, 'lacuna', 'grammar', '___ you ever ___ a presentation in English?', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('9e1253e4-1ff2-58d8-ab52-80d5a1778829', '{"lacunas": [["Have"], ["given", "made", "done"]], "ignorar_acentos": false}'::jsonb, 'Experiência de vida (ever): Have you ever + particípio?');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e404a621-b746-5921-a2c2-14bab6785aad', '396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 3, 'lacuna', 'grammar', 'I have lived in Recife ___ 2015.', '{"banco": ["for", "since", "ago"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e404a621-b746-5921-a2c2-14bab6785aad', '{"lacunas": [["since"]], "ignorar_acentos": false}'::jsonb, 'Since + ponto de início (2015).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('39e05311-5138-55c7-b0e5-70de4f33cad7', '396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 4, 'lacuna', 'grammar', 'We finished the report two days ___.', '{"banco": ["for", "since", "ago"]}'::jsonb);
