insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7bdb0203-96e7-5364-b940-db176e102c54', '396bbd34-3e31-50b3-ae8a-005303cde092', '8ea30ab2-a016-534c-8871-0e2a9c154658', 5, 'multipla_escolha', 'grammar', 'Which sentence is correct?', '{"opcoes": ["I have finished the project last month.", "I have finish the project last month.", "I finished the project last month."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('7bdb0203-96e7-5364-b940-db176e102c54', '{"correta": 2}'::jsonb, 'Last month é tempo definido: past simple.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('e1f75ebd-7094-5222-965f-72666f5cb4f7', 'Renting a flat', 'Must, have to, don''t have to, mustn''t', 'Entenda as regras antes de assinar o contrato.', 'ingles', 4, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('bf4b378a-1d43-562d-bc59-852f336af57e', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 0, 'Dica', '', 'dica', '{"texto": "Have to = obrigação externa (regra, contrato). Must = obrigação que quem fala considera importante, comum em avisos. Atenção: don''t have to = não é necessário; mustn''t = é proibido. Parecem iguais, mas o sentido é bem diferente!"}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('92c9626c-5fc0-5610-ac6d-a6ab379568fe', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 1, 'Listening: Visiting a flat', 'Ouça a visita ao apartamento e responda.', 'audio', '{"roteiro": "AGENT: So, this is the living room. As you can see, it gets a lot of natural light.\nCAROLINA: It''s lovely. How much is the rent?\nAGENT: It''s nine hundred pounds a month, and bills are included, except electricity.\nCAROLINA: Do I have to pay a deposit?\nAGENT: Yes, you have to pay one month''s rent as a deposit. You get it back at the end of the contract.\nCAROLINA: And how long is the contract?\nAGENT: Twelve months minimum. You don''t have to pay any agency fees, though.\nCAROLINA: Great. Can I have pets? I have a cat.\nAGENT: Cats are fine, but you mustn''t smoke inside the flat. It''s in the contract.\nCAROLINA: That''s not a problem, I don''t smoke. When can I move in?\nAGENT: From the first of next month.", "generos": {"AGENT": "masculina", "CAROLINA": "feminina"}, "vozes": {"AGENT": "Puck", "CAROLINA": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-05-renting-a-flat.mp3", "audio_assinatura": "AGENT=Puck;CAROLINA=Kore|AGENT: So, this is the living room. As you can see, it gets a lot of natural light.\nCAROLINA: It''s lovely. How much is the rent?\nAGENT: It''s nine hundred pounds a month, and bills are included, except electricity.\nCAROLINA: Do I have to pay a deposit?\nAGENT: Yes, you have to pay one month''s rent as a deposit. You get it back at the end of the contract.\nCAROLINA: And how long is the contract?\nAGENT: Twelve months minimum. You don''t have to pay any agency fees, though.\nCAROLINA: Great. Can I have pets? I have a cat.\nAGENT: Cats are fine, but you mustn''t smoke inside the flat. It''s in the contract.\nCAROLINA: That''s not a problem, I don''t smoke. When can I move in?\nAGENT: From the first of next month.", "duracao": 57.2}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('cfb35a9f-5b10-563c-9768-8b416fddde73', '92c9626c-5fc0-5610-ac6d-a6ab379568fe', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 0, 'multipla_escolha', 'listening', 'How much is the rent?', '{"opcoes": ["£800 a month", "£900 a month", "£1,900 a month"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('cfb35a9f-5b10-563c-9768-8b416fddde73', '{"correta": 1}'::jsonb, 'Nine hundred pounds a month.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('a286aa77-6568-501a-ba41-ffd5a53789d4', '92c9626c-5fc0-5610-ac6d-a6ab379568fe', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 1, 'multipla_escolha', 'listening', 'Which bill is NOT included?', '{"opcoes": ["Water", "Internet", "Electricity"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('a286aa77-6568-501a-ba41-ffd5a53789d4', '{"correta": 2}'::jsonb, 'Bills are included, except electricity.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('9b349952-8b41-505a-8c8c-cf34194d3742', '92c9626c-5fc0-5610-ac6d-a6ab379568fe', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 2, 'verdadeiro_falso', 'listening', 'Carolina has to pay agency fees.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('9b349952-8b41-505a-8c8c-cf34194d3742', '{"valor": false}'::jsonb, 'You don''t have to pay any agency fees = não precisa pagar.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('bf24afb2-eb46-53c1-bd5a-1eb43804597f', '92c9626c-5fc0-5610-ac6d-a6ab379568fe', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 3, 'verdadeiro_falso', 'listening', 'Carolina can live in the flat with her cat.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('bf24afb2-eb46-53c1-bd5a-1eb43804597f', '{"valor": true}'::jsonb, 'O corretor diz: Cats are fine.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('73364f9d-a085-5195-b472-a945c42591ce', '92c9626c-5fc0-5610-ac6d-a6ab379568fe', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 4, 'multipla_escolha', 'listening', 'How long is the minimum contract?', '{"opcoes": ["Six months", "Twelve months", "Twenty-four months"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('73364f9d-a085-5195-b472-a945c42591ce', '{"correta": 1}'::jsonb, 'Twelve months minimum.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 2, 'Obrigação, proibição ou opção?', 'Escolha ou escreva o modal certo.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('4723d3c8-d102-5177-883f-0f88f1fb6fd5', '8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 0, 'lacuna_opcoes', 'grammar', 'You ___ wear a suit. The dress code here is casual.', '{"opcoes": [["mustn''t", "don''t have to"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('4723d3c8-d102-5177-883f-0f88f1fb6fd5', '{"lacunas": [1]}'::jsonb, 'Não é necessário (mas pode): don''t have to.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('94924232-50cd-5904-b133-f7cf2f662dd4', '8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 1, 'lacuna_opcoes', 'grammar', 'Visitors ___ feed the animals. It''s dangerous.', '{"opcoes": [["mustn''t", "don''t have to"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('94924232-50cd-5904-b133-f7cf2f662dd4', '{"lacunas": [0]}'::jsonb, 'É proibido: mustn''t.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('afd30773-3553-5157-8064-16287396a0e2', '8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 2, 'lacuna', 'grammar', 'In Brazil, you ___ be 18 to get a driving licence.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('afd30773-3553-5157-8064-16287396a0e2', '{"lacunas": [["have to", "must"]], "ignorar_acentos": false}'::jsonb, 'Obrigação por lei: have to (ou must).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('98126eec-786b-5979-b7d8-108f56d91a41', '8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 3, 'lacuna', 'grammar', 'She ___ to work on Saturdays last year.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('98126eec-786b-5979-b7d8-108f56d91a41', '{"lacunas": [["had"]], "ignorar_acentos": false}'::jsonb, 'O passado de have to é had to; must não tem passado.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('a99925e5-dc5b-5734-afc0-e0f580debeb2', '8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 4, 'multipla_escolha', 'vocabulary', '"You don''t have to come" means:', '{"opcoes": ["Você não pode vir.", "Você não precisa vir.", "Você não deve vir de jeito nenhum."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('a99925e5-dc5b-5734-afc0-e0f580debeb2', '{"correta": 1}'::jsonb, 'Don''t have to = não é necessário.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('faa47f73-d9cf-5b76-8035-c6fe9e4a575b', '8d957831-a56a-5df4-bee9-bc87f3d12790', 'e1f75ebd-7094-5222-965f-72666f5cb4f7', 5, 'completar_letras', 'vocabulary', 'Lan_lord (dono do imóvel)', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('faa47f73-d9cf-5b76-8035-c6fe9e4a575b', '{"lacunas": [["d"]], "ignorar_acentos": false}'::jsonb, 'Landlord: o proprietário que aluga o imóvel.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('3afd8890-ee49-52f4-9898-7ca9dee40651', 'Working remotely', 'Second and third conditionals', 'Hipóteses, arrependimentos e decisões do trabalho remoto.', 'ingles', 5, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('552ae583-2f59-566f-bf01-acce009dad13', '3afd8890-ee49-52f4-9898-7ca9dee40651', 0, 'Dica', '', 'dica', '{"texto": "Second conditional = situação imaginária no presente ou futuro: If I worked from home, I''d save two hours a day. Third conditional = passado que não aconteceu: If we had tested the app, we wouldn''t have lost the client. Depois de if não usamos would."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('b5e65b1f-73d2-55ab-b794-34f4f058b85c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 1, 'Listening: A video call that went wrong', 'Ouça a chamada e responda.', 'audio', '{"roteiro": "MAYA: James, can you hear me now? Sorry, my connection dropped again.\nJAMES: Yes, you''re back. Honestly, if you''d told me earlier that your internet was unstable, we could have moved the call to the afternoon.\nMAYA: I know. I didn''t expect it to be this bad. The provider is doing some work on my street.\nJAMES: OK, let''s be quick then. The client wants the proposal by Thursday instead of Friday.\nMAYA: Thursday? If we had one more designer, that would be easy, but right now it''s just me.\nJAMES: What if I asked Priya to help you with the slides? She finished her project yesterday.\nMAYA: That would be amazing. If she took the slides, I''d focus on the budget.\nJAMES: Done. I''ll message her right after this call. And Maya, maybe work from the coworking space tomorrow?\nMAYA: Good idea. If I''d gone there today, none of this would have happened.", "generos": {"MAYA": "feminina", "JAMES": "masculina"}, "vozes": {"MAYA": "Kore", "JAMES": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-06-working-remotely.mp3", "audio_assinatura": "JAMES=Puck;MAYA=Kore|MAYA: James, can you hear me now? Sorry, my connection dropped again.\nJAMES: Yes, you''re back. Honestly, if you''d told me earlier that your internet was unstable, we could have moved the call to the afternoon.\nMAYA: I know. I didn''t expect it to be this bad. The provider is doing some work on my street.\nJAMES: OK, let''s be quick then. The client wants the proposal by Thursday instead of Friday.\nMAYA: Thursday? If we had one more designer, that would be easy, but right now it''s just me.\nJAMES: What if I asked Priya to help you with the slides? She finished her project yesterday.\nMAYA: That would be amazing. If she took the slides, I''d focus on the budget.\nJAMES: Done. I''ll message her right after this call. And Maya, maybe work from the coworking space tomorrow?\nMAYA: Good idea. If I''d gone there today, none of this would have happened.", "duracao": 65.4}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('63108ca3-4a22-5fd1-bca4-9ac07a6823c1', 'b5e65b1f-73d2-55ab-b794-34f4f058b85c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 0, 'multipla_escolha', 'listening', 'Why does Maya''s connection keep dropping?', '{"opcoes": ["Her laptop is old", "The provider is working on her street", "She is travelling"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('63108ca3-4a22-5fd1-bca4-9ac07a6823c1', '{"correta": 1}'::jsonb, 'The provider is doing some work on my street.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('fcce6b63-7830-5d95-80fa-0e898b7ad4a2', 'b5e65b1f-73d2-55ab-b794-34f4f058b85c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 1, 'multipla_escolha', 'listening', 'What has changed about the deadline?', '{"opcoes": ["It''s now Friday instead of Thursday", "It''s now Thursday instead of Friday", "It has been cancelled"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('fcce6b63-7830-5d95-80fa-0e898b7ad4a2', '{"correta": 1}'::jsonb, 'O cliente quer a proposta na quinta, não mais na sexta.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('93030557-1136-57c7-aca6-1d07a6875595', 'b5e65b1f-73d2-55ab-b794-34f4f058b85c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 2, 'verdadeiro_falso', 'listening', 'Priya is busy with another project.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('93030557-1136-57c7-aca6-1d07a6875595', '{"valor": false}'::jsonb, 'Ela terminou o projeto dela ontem.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('3ce01609-575f-5202-9cd1-dc1befe7df23', 'b5e65b1f-73d2-55ab-b794-34f4f058b85c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 3, 'multipla_escolha', 'listening', 'If Priya helps, what will Maya do?', '{"opcoes": ["Make the slides", "Call the client", "Focus on the budget"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('3ce01609-575f-5202-9cd1-dc1befe7df23', '{"correta": 2}'::jsonb, 'If she took the slides, I''d focus on the budget.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('b7e7e255-60ab-5a93-a112-edaab6a58e44', 'b5e65b1f-73d2-55ab-b794-34f4f058b85c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 4, 'verdadeiro_falso', 'listening', 'Maya regrets not working from the coworking space today.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('b7e7e255-60ab-5a93-a112-edaab6a58e44', '{"valor": true}'::jsonb, 'If I''d gone there today, none of this would have happened: arrependimento (third conditional).');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 2, 'Second ou third conditional?', 'Pense se a situação é imaginária no presente ou no passado.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('ffb4f334-c63b-5cb5-9469-f60a52d5fc35', 'afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 0, 'lacuna_opcoes', 'grammar', 'If I ___ more time, I would learn Italian.', '{"opcoes": [["have", "had", "would have"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('ffb4f334-c63b-5cb5-9469-f60a52d5fc35', '{"lacunas": [1]}'::jsonb, 'Second conditional: if + past simple.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('59d3cf63-183f-542b-8b0c-39ca1e2a991d', 'afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 1, 'lacuna_opcoes', 'grammar', 'If they had left earlier, they ___ the train.', '{"opcoes": [["would catch", "would have caught", "had caught"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('59d3cf63-183f-542b-8b0c-39ca1e2a991d', '{"lacunas": [1]}'::jsonb, 'Third conditional: would have + particípio.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('72019012-2138-5715-9cb1-a3821fa14c67', 'afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 2, 'lacuna', 'grammar', 'If she ___ (know) about the meeting, she would have come.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('72019012-2138-5715-9cb1-a3821fa14c67', '{"lacunas": [["had known"]], "ignorar_acentos": false}'::jsonb, 'Third conditional: if + past perfect (had known).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('65d96219-85a2-57c7-8f60-46e96c1aaa56', 'afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 3, 'lacuna', 'grammar', 'What ___ you do if you lost your job tomorrow?', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('65d96219-85a2-57c7-8f60-46e96c1aaa56', '{"lacunas": [["would"]], "ignorar_acentos": false}'::jsonb, 'Pergunta hipotética no second conditional: What would you do...?');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('18d7cf24-ea5b-54e3-b1a8-e4dd75b9af58', 'afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 4, 'multipla_escolha', 'grammar', 'Which sentence expresses regret about the past?', '{"opcoes": ["If I study more, I''ll pass.", "If I studied more, I''d pass.", "If I had studied more, I would have passed."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('18d7cf24-ea5b-54e3-b1a8-e4dd75b9af58', '{"correta": 2}'::jsonb, 'Arrependimento sobre o passado: third conditional.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('97b23ae2-5635-56aa-aeab-4b8f31255256', 'afbfd259-bf6b-556e-9f88-de573be6c98c', '3afd8890-ee49-52f4-9898-7ca9dee40651', 5, 'resposta_curta', 'writing', 'Reescreva com third conditional: I didn''t know you were in town, so I didn''t call you. (Comece com: If I had...)', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('97b23ae2-5635-56aa-aeab-4b8f31255256', '{"aceitas": ["If I had known you were in town, I would have called you", "If I''d known you were in town, I would have called you", "If I had known you were in town, I''d have called you", "If I''d known you were in town, I''d have called you", "If I had known you were in town I would have called you", "If I''d known you were in town I would have called you", "If I had known you were in town I''d have called you", "If I''d known you were in town I''d have called you"], "ignorar_acentos": false}'::jsonb, 'If + had known, + would have called: a situação real foi o contrário.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('fb1bda08-1f91-5a25-9676-4822a2d11bb0', 'Handling customer complaints', 'Reported speech', 'Relate o que o cliente disse com precisão e profissionalismo.', 'ingles', 5, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('25df6d20-172a-57ac-a9c3-9816dcc5f36f', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 0, 'Dica', '', 'dica', '{"texto": "No reported speech, o tempo verbal costuma voltar um passo: ''I am upset'' → She said she was upset; ''We will refund you'' → They said they would refund me. Say não leva objeto (she said that...); tell sempre diz para quem (she told me that...)."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('c5482132-724d-5b4d-a311-0f1a08afed21', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 1, 'Listening: A complaint call', 'Ouça a ligação para o atendimento e responda.', 'audio', '{"roteiro": "HANNAH: Good morning, Brightline Electronics, Hannah speaking. How can I help?\nCOOPER: Hi. I bought a coffee machine from your website two weeks ago, and it stopped working yesterday.\nHANNAH: I''m sorry to hear that. Could you give me your order number, please?\nCOOPER: It''s B four seven two nine.\nHANNAH: Thank you, Mr Cooper. I can see the order. What exactly happens when you turn it on?\nCOOPER: The light comes on, but no water comes out. And to be honest, I''ve already called twice and nobody called me back.\nHANNAH: I do apologise for that. Here''s what I can do: we''ll send a courier to collect the machine tomorrow, and you''ll get a brand-new one within five working days.\nCOOPER: Can''t I just get a refund?\nHANNAH: Of course. If you prefer, we''ll refund the full amount as soon as we receive the machine.\nCOOPER: Then I''d rather have the refund, thanks.", "generos": {"HANNAH": "feminina", "COOPER": "masculina"}, "vozes": {"HANNAH": "Kore", "COOPER": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-07-handling-customer-complaints.mp3", "audio_assinatura": "COOPER=Puck;HANNAH=Kore|HANNAH: Good morning, Brightline Electronics, Hannah speaking. How can I help?\nCOOPER: Hi. I bought a coffee machine from your website two weeks ago, and it stopped working yesterday.\nHANNAH: I''m sorry to hear that. Could you give me your order number, please?\nCOOPER: It''s B four seven two nine.\nHANNAH: Thank you, Mr Cooper. I can see the order. What exactly happens when you turn it on?\nCOOPER: The light comes on, but no water comes out. And to be honest, I''ve already called twice and nobody called me back.\nHANNAH: I do apologise for that. Here''s what I can do: we''ll send a courier to collect the machine tomorrow, and you''ll get a brand-new one within five working days.\nCOOPER: Can''t I just get a refund?\nHANNAH: Of course. If you prefer, we''ll refund the full amount as soon as we receive the machine.\nCOOPER: Then I''d rather have the refund, thanks.", "duracao": 61.4}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('5a587262-eeee-56c2-b9ee-47f007b2af96', 'c5482132-724d-5b4d-a311-0f1a08afed21', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 0, 'multipla_escolha', 'listening', 'When did the machine stop working?', '{"opcoes": ["Two weeks ago", "Yesterday", "This morning"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('5a587262-eeee-56c2-b9ee-47f007b2af96', '{"correta": 1}'::jsonb, 'Ele comprou há duas semanas; parou de funcionar ontem.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('1ace9ff2-16ac-5985-bd95-7014be851258', 'c5482132-724d-5b4d-a311-0f1a08afed21', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 1, 'multipla_escolha', 'listening', 'What is the problem with the machine?', '{"opcoes": ["The light doesn''t come on", "It makes a strange noise", "No water comes out"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('1ace9ff2-16ac-5985-bd95-7014be851258', '{"correta": 2}'::jsonb, 'The light comes on, but no water comes out.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('5447fc35-623a-5d93-adfb-10acae914894', 'c5482132-724d-5b4d-a311-0f1a08afed21', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 2, 'verdadeiro_falso', 'listening', 'This is the first time Mr Cooper has called.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('5447fc35-623a-5d93-adfb-10acae914894', '{"valor": false}'::jsonb, 'Ele já ligou duas vezes antes (I''ve already called twice).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('680c813b-6ef6-5367-959f-8e322d73ba4f', 'c5482132-724d-5b4d-a311-0f1a08afed21', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 3, 'multipla_escolha', 'listening', 'How long would a replacement take?', '{"opcoes": ["Two working days", "Five working days", "Two weeks"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('680c813b-6ef6-5367-959f-8e322d73ba4f', '{"correta": 1}'::jsonb, 'Within five working days.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('81c6b617-40a0-57ed-9658-246a5e66b0ae', 'c5482132-724d-5b4d-a311-0f1a08afed21', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 4, 'multipla_escolha', 'listening', 'What does Mr Cooper finally choose?', '{"opcoes": ["A new machine", "A discount", "A refund"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('81c6b617-40a0-57ed-9658-246a5e66b0ae', '{"correta": 2}'::jsonb, 'I''d rather have the refund.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 2, 'Relatando o que foi dito', 'Passe para o reported speech.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('cbc5d86a-5415-5b25-8c44-416e6a68ad9f', '672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 0, 'lacuna', 'grammar', '"I am very disappointed." → She said she ___ very disappointed.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('cbc5d86a-5415-5b25-8c44-416e6a68ad9f', '{"lacunas": [["was"]], "ignorar_acentos": false}'::jsonb, 'Am volta para was.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('eb6e5d2e-8672-5e5e-9f03-7a7161940588', '672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 1, 'lacuna', 'grammar', '"We will call you back." → They said they ___ call me back.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('eb6e5d2e-8672-5e5e-9f03-7a7161940588', '{"lacunas": [["would"]], "ignorar_acentos": false}'::jsonb, 'Will volta para would.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('5a01685c-aaa5-5cd8-80d3-830326339b24', '672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 2, 'lacuna_opcoes', 'grammar', 'He ___ me that the order had been cancelled.', '{"opcoes": [["said", "told"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('5a01685c-aaa5-5cd8-80d3-830326339b24', '{"lacunas": [1]}'::jsonb, 'Com objeto (me), usamos told.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2108abf5-39e0-57e7-9303-21ebb41d0735', '672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 3, 'lacuna_opcoes', 'grammar', 'She ___ that she had never received the invoice.', '{"opcoes": [["said", "told"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2108abf5-39e0-57e7-9303-21ebb41d0735', '{"lacunas": [0]}'::jsonb, 'Sem dizer para quem, usamos said.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('35e025b4-2407-5731-a99a-9c5ee2e09f12', '672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 4, 'lacuna', 'grammar', '"I have sent the email." → He said he ___ ___ the email.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('35e025b4-2407-5731-a99a-9c5ee2e09f12', '{"lacunas": [["had"], ["sent"]], "ignorar_acentos": false}'::jsonb, 'Present perfect volta para past perfect: had sent.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('bd9e0296-24f5-5a95-b4b5-54a515981e9e', '672d22e8-c14b-54c5-b174-932bd1a22e05', 'fb1bda08-1f91-5a25-9676-4822a2d11bb0', 5, 'multipla_escolha', 'grammar', '"Can you help me?" → reported question:', '{"opcoes": ["She asked can I help her.", "She asked if I could help her.", "She said could I help her."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('bd9e0296-24f5-5a95-b4b5-54a515981e9e', '{"correta": 1}'::jsonb, 'Pergunta indireta: asked if + ordem de afirmação (I could).');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('0d48bd16-6523-5af1-b333-f4905d641745', 'Negotiating a deal', 'Hedging and diplomatic language', 'Negocie com firmeza sem perder a elegância.', 'ingles', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('658269ae-6665-520c-b1cd-91dc9e530067', '0d48bd16-6523-5af1-b333-f4905d641745', 0, 'Dica', '', 'dica', '{"texto": "Em negociações, nativos suavizam o que dizem (hedging): I''m afraid that might be a bit difficult; We were hoping for something closer to...; Would you be open to...? O passado (we were hoping) e os modais (might, could) soam menos diretos e mais profissionais."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('fbf8d887-9648-5e59-842c-efc405dd9e7c', '0d48bd16-6523-5af1-b333-f4905d641745', 1, 'Listening: Closing the contract', 'Ouça a negociação e responda.', 'audio', '{"roteiro": "OMAR: Thanks for sending the revised proposal, Clara. Overall, we''re quite happy with it, but I''m afraid the price is still a little above our budget.\nCLARA: I appreciate your honesty. Could you give me a sense of the figure you had in mind?\nOMAR: We were hoping for something closer to forty thousand for the first year.\nCLARA: I see. That would be a fifteen percent reduction, which would be difficult for us to absorb on our own. However, if you were open to a two-year contract, we might be able to meet you halfway.\nOMAR: That''s an interesting option. What would halfway look like, in practice?\nCLARA: Forty-three thousand per year, with onboarding and training included at no extra cost.\nOMAR: That sounds reasonable. I''d need to run it past our finance director, but I think we''re close.\nCLARA: Of course. Shall I put that in writing so you have something concrete to share?\nOMAR: That would be very helpful. Let''s aim to sign by the end of the month.", "generos": {"OMAR": "masculina", "CLARA": "feminina"}, "vozes": {"OMAR": "Puck", "CLARA": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-08-negotiating-a-deal.mp3", "audio_assinatura": "CLARA=Kore;OMAR=Puck|OMAR: Thanks for sending the revised proposal, Clara. Overall, we''re quite happy with it, but I''m afraid the price is still a little above our budget.\nCLARA: I appreciate your honesty. Could you give me a sense of the figure you had in mind?\nOMAR: We were hoping for something closer to forty thousand for the first year.\nCLARA: I see. That would be a fifteen percent reduction, which would be difficult for us to absorb on our own. However, if you were open to a two-year contract, we might be able to meet you halfway.\nOMAR: That''s an interesting option. What would halfway look like, in practice?\nCLARA: Forty-three thousand per year, with onboarding and training included at no extra cost.\nOMAR: That sounds reasonable. I''d need to run it past our finance director, but I think we''re close.\nCLARA: Of course. Shall I put that in writing so you have something concrete to share?\nOMAR: That would be very helpful. Let''s aim to sign by the end of the month.", "duracao": 66.9}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('0fd0d556-21ad-5a89-be99-8b150169882d', 'fbf8d887-9648-5e59-842c-efc405dd9e7c', '0d48bd16-6523-5af1-b333-f4905d641745', 0, 'multipla_escolha', 'listening', 'What is Omar''s main concern?', '{"opcoes": ["The delivery time", "The price", "The quality of the training"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('0fd0d556-21ad-5a89-be99-8b150169882d', '{"correta": 1}'::jsonb, 'The price is still a little above our budget.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('67661cbc-120a-5d3d-856e-3c459486ecf9', 'fbf8d887-9648-5e59-842c-efc405dd9e7c', '0d48bd16-6523-5af1-b333-f4905d641745', 1, 'multipla_escolha', 'listening', 'What does Clara ask for in exchange for a lower price?', '{"opcoes": ["Payment in advance", "A bigger order", "A two-year contract"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('67661cbc-120a-5d3d-856e-3c459486ecf9', '{"correta": 2}'::jsonb, 'If you were open to a two-year contract...');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('68ea5565-148e-574b-8d1b-d668b9b0c46c', 'fbf8d887-9648-5e59-842c-efc405dd9e7c', '0d48bd16-6523-5af1-b333-f4905d641745', 2, 'verdadeiro_falso', 'listening', 'The final offer includes training at no extra cost.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('68ea5565-148e-574b-8d1b-d668b9b0c46c', '{"valor": true}'::jsonb, 'Onboarding and training included at no extra cost.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('84bc7766-863e-5fb2-a013-195e06cd00d3', 'fbf8d887-9648-5e59-842c-efc405dd9e7c', '0d48bd16-6523-5af1-b333-f4905d641745', 3, 'multipla_escolha', 'listening', 'What does Omar still need to do?', '{"opcoes": ["Talk to the finance director", "Visit Clara''s office", "Send a new proposal"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('84bc7766-863e-5fb2-a013-195e06cd00d3', '{"correta": 0}'::jsonb, 'I''d need to run it past our finance director.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('9810063f-bf37-5ab4-938f-aafdb06fb4b7', 'fbf8d887-9648-5e59-842c-efc405dd9e7c', '0d48bd16-6523-5af1-b333-f4905d641745', 4, 'multipla_escolha', 'listening', 'In this conversation, "meet you halfway" means:', '{"opcoes": ["Accept the client''s price", "Find a compromise between both prices", "Meet in person"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('9810063f-bf37-5ab4-938f-aafdb06fb4b7', '{"correta": 1}'::jsonb, 'Meet halfway = ceder um pouco cada lado.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 2, 'Diplomatic language', 'Escolha a forma mais natural numa negociação.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('cc939230-d310-550d-b99f-157f7042a3b0', 'ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 0, 'multipla_escolha', 'vocabulary', 'Which is the most diplomatic way to say "Your price is too high"?', '{"opcoes": ["Your price is too high.", "Lower your price.", "I''m afraid the price is slightly higher than we expected."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('cc939230-d310-550d-b99f-157f7042a3b0', '{"correta": 2}'::jsonb, 'I''m afraid + slightly suavizam a crítica.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('639bbdb9-235e-5213-bd7f-671b05983091', 'ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 1, 'lacuna_opcoes', 'grammar', 'We ___ wondering if you could extend the deadline.', '{"opcoes": [["are", "were"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('639bbdb9-235e-5213-bd7f-671b05983091', '{"lacunas": [1]}'::jsonb, 'O past continuous (we were wondering) deixa o pedido mais educado.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('af19a460-e2cc-50c0-ac60-0c4faf53a316', 'ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 2, 'lacuna', 'grammar', 'Would you be open ___ discussing the payment terms?', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('af19a460-e2cc-50c0-ac60-0c4faf53a316', '{"lacunas": [["to"]], "ignorar_acentos": false}'::jsonb, 'Be open to + verbo com -ing.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('55336cdd-b097-5dfa-ba86-efdc1e22394a', 'ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 3, 'lacuna_opcoes', 'grammar', 'That ___ be a problem for our team.', '{"opcoes": [["will", "might"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('55336cdd-b097-5dfa-ba86-efdc1e22394a', '{"lacunas": [1]}'::jsonb, 'Might suaviza: talvez seja um problema.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('d949fe4d-f959-579d-b4d3-130901a0e7ae', 'ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 4, 'lacuna', 'vocabulary', 'I need to run it ___ my manager before I can say yes.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('d949fe4d-f959-579d-b4d3-130901a0e7ae', '{"lacunas": [["past", "by"]], "ignorar_acentos": false}'::jsonb, 'Run something past/by someone = consultar alguém antes de decidir.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c43a6158-adc0-5cba-a1c9-d9f86da63fb3', 'ac6cfc22-eb09-5ba8-946d-19775f168f8e', '0d48bd16-6523-5af1-b333-f4905d641745', 5, 'verdadeiro_falso', 'vocabulary', 'A "ballpark figure" is an approximate number.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c43a6158-adc0-5cba-a1c9-d9f86da63fb3', '{"valor": true}'::jsonb, 'Ballpark figure = valor aproximado, estimativa.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('7a629608-6250-55d3-b182-95491631c4c8', 'Giving feedback at work', 'Phrasal verbs & idioms for the workplace', 'Dê e receba feedback com a naturalidade de um nativo.', 'ingles', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('4a463e1c-5a2e-5297-acb7-01cbed85559e', '7a629608-6250-55d3-b182-95491631c4c8', 0, 'Dica', '', 'dica', '{"texto": "Phrasal verbs e expressões deixam o feedback mais natural: bring up (trazer um assunto), follow up (dar continuidade), take on (assumir), be on the same page (estar alinhados). E fale do comportamento, não da pessoa: ''The report came in late'' em vez de ''You''re always late''."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('ab5eea84-e8b9-5bd1-a3d5-356d3b899150', '7a629608-6250-55d3-b182-95491631c4c8', 1, 'Listening: A one-to-one meeting', 'Ouça a conversa entre gestora e funcionário e responda.', 'audio', '{"roteiro": "DIANA: Thanks for making time, Ethan. I wanted to touch base about the last quarter.\nETHAN: Sure. Is everything OK?\nDIANA: Overall, yes. Your presentation to the board went down really well. They specifically mentioned your analysis of the Asian market.\nETHAN: That''s great to hear. I put a lot of work into that.\nDIANA: It showed. There''s one thing I''d like to bring up, though. A couple of reports came in after the deadline, and that held up the finance team.\nETHAN: You''re right. I took on too much this quarter and lost track of a few things.\nDIANA: I appreciate you owning that. How about we sit down every Monday to prioritise your tasks, so we''re on the same page?\nETHAN: That would really help. Should I also hand over the client newsletter to someone else?\nDIANA: Good idea. Let''s talk to Sam about it. And keep up the good work on the analysis. It really stood out.", "generos": {"DIANA": "feminina", "ETHAN": "masculina"}, "vozes": {"DIANA": "Kore", "ETHAN": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-09-giving-feedback-at-work.mp3", "audio_assinatura": "DIANA=Kore;ETHAN=Puck|DIANA: Thanks for making time, Ethan. I wanted to touch base about the last quarter.\nETHAN: Sure. Is everything OK?\nDIANA: Overall, yes. Your presentation to the board went down really well. They specifically mentioned your analysis of the Asian market.\nETHAN: That''s great to hear. I put a lot of work into that.\nDIANA: It showed. There''s one thing I''d like to bring up, though. A couple of reports came in after the deadline, and that held up the finance team.\nETHAN: You''re right. I took on too much this quarter and lost track of a few things.\nDIANA: I appreciate you owning that. How about we sit down every Monday to prioritise your tasks, so we''re on the same page?\nETHAN: That would really help. Should I also hand over the client newsletter to someone else?\nDIANA: Good idea. Let''s talk to Sam about it. And keep up the good work on the analysis. It really stood out.", "duracao": 64.9}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('bf0b4daa-ad8c-5f29-bd3a-fefb997e6338', 'ab5eea84-e8b9-5bd1-a3d5-356d3b899150', '7a629608-6250-55d3-b182-95491631c4c8', 0, 'multipla_escolha', 'listening', 'What did the board like?', '{"opcoes": ["Ethan''s budget", "Ethan''s analysis of the Asian market", "Ethan''s newsletter"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('bf0b4daa-ad8c-5f29-bd3a-fefb997e6338', '{"correta": 1}'::jsonb, 'They specifically mentioned your analysis of the Asian market.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f9b00386-d9eb-58e7-9663-8265b9289b15', 'ab5eea84-e8b9-5bd1-a3d5-356d3b899150', '7a629608-6250-55d3-b182-95491631c4c8', 1, 'multipla_escolha', 'listening', 'What problem does Diana bring up?', '{"opcoes": ["Ethan was rude to a client", "Some reports were late", "The presentation was too long"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('f9b00386-d9eb-58e7-9663-8265b9289b15', '{"correta": 1}'::jsonb, 'A couple of reports came in after the deadline.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f68bf11a-fa28-5925-a12b-5bf67918c0cd', 'ab5eea84-e8b9-5bd1-a3d5-356d3b899150', '7a629608-6250-55d3-b182-95491631c4c8', 2, 'multipla_escolha', 'listening', 'According to Ethan, why did it happen?', '{"opcoes": ["He took on too many tasks", "He was on holiday", "He misunderstood the deadline"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('f68bf11a-fa28-5925-a12b-5bf67918c0cd', '{"correta": 0}'::jsonb, 'I took on too much this quarter.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7f7a9b27-0ec9-52a6-b87a-cf93fc1444b8', 'ab5eea84-e8b9-5bd1-a3d5-356d3b899150', '7a629608-6250-55d3-b182-95491631c4c8', 3, 'verdadeiro_falso', 'listening', 'They agree to meet every Friday.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('7f7a9b27-0ec9-52a6-b87a-cf93fc1444b8', '{"valor": false}'::jsonb, 'As reuniões serão toda segunda-feira (every Monday).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('b83b09f7-834f-5c30-8d8d-6625aa52a878', 'ab5eea84-e8b9-5bd1-a3d5-356d3b899150', '7a629608-6250-55d3-b182-95491631c4c8', 4, 'verdadeiro_falso', 'listening', 'Ethan suggests passing the newsletter to someone else.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('b83b09f7-834f-5c30-8d8d-6625aa52a878', '{"valor": true}'::jsonb, 'Should I also hand over the client newsletter to someone else?');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 2, 'Phrasal verbs e expressões', 'Complete ou escolha o significado.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('4929b9ab-f24e-5ef5-a008-ac9e68fa08d6', '0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 0, 'lacuna', 'vocabulary', 'The late reports held ___ the finance team.', '{"banco": ["up", "out", "on"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('4929b9ab-f24e-5ef5-a008-ac9e68fa08d6', '{"lacunas": [["up"]], "ignorar_acentos": false}'::jsonb, 'Hold up = atrasar alguém ou algo.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('4daee039-6e65-5f96-a4dc-3bb702e2aeea', '0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 1, 'lacuna', 'vocabulary', 'I''ll follow ___ with an email after the meeting.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('4daee039-6e65-5f96-a4dc-3bb702e2aeea', '{"lacunas": [["up"]], "ignorar_acentos": false}'::jsonb, 'Follow up = dar continuidade, retomar o assunto.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f2062085-87be-570d-9496-1749f7c797e0', '0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 2, 'lacuna_opcoes', 'vocabulary', 'I took ___ too many projects this year.', '{"opcoes": [["over", "on", "up"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('f2062085-87be-570d-9496-1749f7c797e0', '{"lacunas": [1]}'::jsonb, 'Take on = assumir (tarefas, responsabilidades).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('d5f6d35b-9ed1-5d22-becf-7b187e6224ec', '0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 3, 'multipla_escolha', 'vocabulary', '"Let''s touch base next week" means:', '{"opcoes": ["Vamos conversar rapidamente semana que vem.", "Vamos visitar a sede semana que vem.", "Vamos encerrar o projeto semana que vem."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('d5f6d35b-9ed1-5d22-becf-7b187e6224ec', '{"correta": 0}'::jsonb, 'Touch base = fazer um contato rápido para se atualizar.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e5159d3b-0afa-514b-b7e6-cf5d124f1057', '0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 4, 'multipla_escolha', 'vocabulary', '"Your presentation went down well" means:', '{"opcoes": ["It was shorter than expected.", "It was received positively.", "It was cancelled."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e5159d3b-0afa-514b-b7e6-cf5d124f1057', '{"correta": 1}'::jsonb, 'Go down well = ser bem recebido.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('bf32d7fa-63f1-56d3-b627-f9eb3f6926ca', '0a2081f8-47f4-5909-b805-779780f9c4fb', '7a629608-6250-55d3-b182-95491631c4c8', 5, 'lacuna', 'vocabulary', 'We need to be on the same ___ before we talk to the client.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('bf32d7fa-63f1-56d3-b627-f9eb3f6926ca', '{"lacunas": [["page"]], "ignorar_acentos": false}'::jsonb, 'Be on the same page = estar alinhados.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('4123ed4a-5221-50b6-948f-7e92c0dbde95', 'The four-day week', 'Discourse markers & advanced vocabulary', 'Um podcast para treinar o ouvido no inglês avançado.', 'ingles', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('e43ac8a4-8cec-577d-9fe1-6dc8f7fedb22', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 0, 'Dica', '', 'dica', '{"texto": "Marcadores do discurso organizam as ideias: however/nevertheless (contraste), moreover/furthermore (adição), therefore/consequently (consequência), in other words (reformulação). Num áudio longo, eles são pistas para você não se perder."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('37a5f4db-f338-5556-8aa7-59b6b1c09c5b', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 1, 'Listening: Work Unplugged podcast', 'Ouça o episódio do podcast e responda.', 'audio', '{"roteiro": "HOST: Welcome back to Work Unplugged. Today I want to talk about something that keeps coming up in our listeners'' messages: the four-day week. Over the past few years, dozens of companies have trialled it, and the results are more nuanced than the headlines suggest.\nHOST: On the one hand, most firms reported that employees were less stressed and took fewer sick days. Moreover, productivity didn''t fall. In several cases, it actually rose, largely because people cut down on unnecessary meetings.\nHOST: On the other hand, the model doesn''t fit every sector. Hospitals and schools, for instance, can''t simply close on Fridays. Consequently, some of them have experimented with rotating schedules instead, which are far harder to manage.\nHOST: There''s also a less obvious risk. When people have to squeeze five days of work into four, the remaining days can become extremely intense. In other words, the problem isn''t the number of days, but how the work itself is organised.\nHOST: So, is the four-day week the future? My take is that it''s a tool, not a magic solution. Nevertheless, it has forced many companies to ask a valuable question: what actually needs to get done, and what are we doing just out of habit?", "generos": {"HOST": "masculina"}, "vozes": {"HOST": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-ingles-10-the-four-day-week.mp3", "audio_assinatura": "HOST=Puck|HOST: Welcome back to Work Unplugged. Today I want to talk about something that keeps coming up in our listeners'' messages: the four-day week. Over the past few years, dozens of companies have trialled it, and the results are more nuanced than the headlines suggest.\nHOST: On the one hand, most firms reported that employees were less stressed and took fewer sick days. Moreover, productivity didn''t fall. In several cases, it actually rose, largely because people cut down on unnecessary meetings.\nHOST: On the other hand, the model doesn''t fit every sector. Hospitals and schools, for instance, can''t simply close on Fridays. Consequently, some of them have experimented with rotating schedules instead, which are far harder to manage.\nHOST: There''s also a less obvious risk. When people have to squeeze five days of work into four, the remaining days can become extremely intense. In other words, the problem isn''t the number of days, but how the work itself is organised.\nHOST: So, is the four-day week the future? My take is that it''s a tool, not a magic solution. Nevertheless, it has forced many companies to ask a valuable question: what actually needs to get done, and what are we doing just out of habit?", "duracao": 80.4}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2645a960-07bf-5c8e-996f-542f376e0232', '37a5f4db-f338-5556-8aa7-59b6b1c09c5b', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 0, 'multipla_escolha', 'listening', 'What is the main topic of the episode?', '{"opcoes": ["Remote work", "Sick leave policies", "The four-day week"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2645a960-07bf-5c8e-996f-542f376e0232', '{"correta": 2}'::jsonb, 'O tema é a semana de quatro dias (four-day week).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c1242b59-8aa0-51ba-a635-84184962985d', '37a5f4db-f338-5556-8aa7-59b6b1c09c5b', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 1, 'verdadeiro_falso', 'listening', 'According to the host, productivity fell in most companies.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c1242b59-8aa0-51ba-a635-84184962985d', '{"valor": false}'::jsonb, 'Productivity didn''t fall; em vários casos, até aumentou.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('51188171-29d6-56f7-929c-aeebd48fc967', '37a5f4db-f338-5556-8aa7-59b6b1c09c5b', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 2, 'multipla_escolha', 'listening', 'Why did productivity rise in several cases?', '{"opcoes": ["People worked longer hours", "People cut down on unnecessary meetings", "Companies hired more staff"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('51188171-29d6-56f7-929c-aeebd48fc967', '{"correta": 1}'::jsonb, 'Largely because people cut down on unnecessary meetings.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7288e73f-663f-559c-956e-5eff0f9c2c62', '37a5f4db-f338-5556-8aa7-59b6b1c09c5b', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 3, 'multipla_escolha', 'listening', 'Why can''t hospitals and schools simply adopt the model?', '{"opcoes": ["It''s too expensive", "They can''t close on a fixed day", "Their employees don''t want it"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('7288e73f-663f-559c-956e-5eff0f9c2c62', '{"correta": 1}'::jsonb, 'They can''t simply close on Fridays.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('de38a6cb-aac3-5520-aa46-2823cd35d1f3', '37a5f4db-f338-5556-8aa7-59b6b1c09c5b', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 4, 'multipla_escolha', 'listening', 'What is the host''s conclusion?', '{"opcoes": ["It''s a magic solution", "It''s a useful tool, not a magic solution", "It should be avoided"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('de38a6cb-aac3-5520-aa46-2823cd35d1f3', '{"correta": 1}'::jsonb, 'It''s a tool, not a magic solution.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 2, 'Discourse markers', 'Escolha o conector que dá sentido à frase.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7a8ff991-4b8c-53a6-a0c2-82554c7fc207', '96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 0, 'lacuna_opcoes', 'grammar', 'The results were positive. ___, some sectors struggled to adapt.', '{"opcoes": [["Moreover", "Nevertheless", "Therefore"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('7a8ff991-4b8c-53a6-a0c2-82554c7fc207', '{"lacunas": [1]}'::jsonb, 'Contraste com a frase anterior: nevertheless.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e0ff57a7-80b7-56d9-934a-54c9b8ba8871', '96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 1, 'lacuna_opcoes', 'grammar', 'Meetings were shorter. ___, people had more time for focused work.', '{"opcoes": [["Consequently", "However", "In other words"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e0ff57a7-80b7-56d9-934a-54c9b8ba8871', '{"lacunas": [0]}'::jsonb, 'Consequência: consequently.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('068174b8-aebe-5e2a-a7dd-bbe2570e18e0', '96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 2, 'multipla_escolha', 'vocabulary', '"The results are more nuanced than the headlines suggest" means:', '{"opcoes": ["The results are more complex than the news says.", "The results are worse than expected.", "The results haven''t been published yet."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('068174b8-aebe-5e2a-a7dd-bbe2570e18e0', '{"correta": 0}'::jsonb, 'Nuanced = com nuances, mais complexo.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('1eab1d72-00c3-5d26-b06c-27e0810937fb', '96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 3, 'lacuna', 'vocabulary', 'Many companies have ___ the model for six months to see if it works.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('1eab1d72-00c3-5d26-b06c-27e0810937fb', '{"lacunas": [["trialled", "trialed", "tested", "piloted"]], "ignorar_acentos": false}'::jsonb, 'Trial (testar por um período): trialled (britânico) ou trialed (americano).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('dc6d430c-9f41-58bd-9bf0-d8806ce694fc', '96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 4, 'lacuna', 'vocabulary', 'We need to cut ___ on unnecessary meetings.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('dc6d430c-9f41-58bd-9bf0-d8806ce694fc', '{"lacunas": [["down"]], "ignorar_acentos": false}'::jsonb, 'Cut down on = reduzir.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2a6c640d-e841-5311-a3f5-d8c1524def10', '96b01297-2ae9-5b0c-8d84-791bbb8264bc', '4123ed4a-5221-50b6-948f-7e92c0dbde95', 5, 'verdadeiro_falso', 'vocabulary', 'Doing something "out of habit" means doing it because you always do it, not because it''s necessary.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2a6c640d-e841-5311-a3f5-d8c1524def10', '{"valor": true}'::jsonb, 'Out of habit = por costume, no automático.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('2899780d-6493-53f2-9473-040f3230016b', '¡Mucho gusto!', 'Presentaciones y el verbo ser', 'O primeiro contato em espanhol, sem medo.', 'espanhol', 1, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('e83877df-679a-5600-8d8f-6d24dee0c288', '2899780d-6493-53f2-9473-040f3230016b', 0, 'Dica', '', 'dica', '{"texto": "Ser: yo soy, tú eres, él/ella/usted es, nosotros somos, ellos son. Para dizer de onde você é: Soy de Brasil. Em espanhol, as perguntas abrem com ¿ e as palavras interrogativas têm acento: ¿Cómo te llamas? ¿De dónde eres?"}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('145e90bb-5bdf-56e2-8cfc-05a19fe3e35f', '2899780d-6493-53f2-9473-040f3230016b', 1, 'Escucha: En la academia', 'Ouça o diálogo e responda.', 'audio', '{"roteiro": "LAURA: ¡Hola! Buenos días. ¿Eres nuevo en el curso?\nMATEO: Sí, soy nuevo. Me llamo Mateo. ¿Y tú?\nLAURA: Yo soy Laura. Mucho gusto, Mateo.\nMATEO: Encantado. ¿De dónde eres, Laura?\nLAURA: Soy de Sevilla, en España. ¿Y tú?\nMATEO: Soy de Brasil, de Belo Horizonte. Soy ingeniero.\nLAURA: ¡Qué bien! Yo soy profesora de música.\nMATEO: ¿Y la clase de español es en esta sala?\nLAURA: No, es en la sala tres, al lado de la cafetería.", "generos": {"LAURA": "feminina", "MATEO": "masculina"}, "vozes": {"LAURA": "Kore", "MATEO": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-01-mucho-gusto.mp3", "audio_assinatura": "LAURA=Kore;MATEO=Puck|LAURA: ¡Hola! Buenos días. ¿Eres nuevo en el curso?\nMATEO: Sí, soy nuevo. Me llamo Mateo. ¿Y tú?\nLAURA: Yo soy Laura. Mucho gusto, Mateo.\nMATEO: Encantado. ¿De dónde eres, Laura?\nLAURA: Soy de Sevilla, en España. ¿Y tú?\nMATEO: Soy de Brasil, de Belo Horizonte. Soy ingeniero.\nLAURA: ¡Qué bien! Yo soy profesora de música.\nMATEO: ¿Y la clase de español es en esta sala?\nLAURA: No, es en la sala tres, al lado de la cafetería.", "duracao": 50.4}'::jsonb);
