insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('78f0fe92-a24a-5813-909f-c510c5623dca', 'De compras en el mercado', 'Precios, números y el verbo gustar', 'Pergunte o preço e escolha o que você gosta.', 'espanhol', 2, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('63963b28-01be-51e7-bc60-0aa027bad67c', '78f0fe92-a24a-5813-909f-c510c5623dca', 0, 'Dica', '', 'dica', '{"texto": "Gustar funciona ao contrário do português: Me gusta el queso (uma coisa) / Me gustan las fresas (várias). O verbo concorda com o que agrada, não com a pessoa. Para perguntar o preço: ¿Cuánto cuesta? (singular) / ¿Cuánto cuestan? (plural)."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('3e7697f5-9528-510a-b1c8-1f6e414cbfaf', '78f0fe92-a24a-5813-909f-c510c5623dca', 1, 'Escucha: En el mercado', 'Ouça as compras de Ana e responda.', 'audio', '{"roteiro": "VENDEDOR: ¡Buenos días! ¿Qué le pongo?\nANA: Buenos días. ¿Cuánto cuestan los tomates?\nVENDEDOR: Dos euros con cincuenta el kilo. Son muy buenos, de la huerta.\nANA: Perfecto, póngame un kilo. ¿Y las fresas?\nVENDEDOR: Las fresas cuestan cuatro euros la caja.\nANA: Mmm, me gustan mucho, pero son un poco caras. Hoy no, gracias.\nVENDEDOR: ¿Algo más?\nANA: Sí, medio kilo de queso manchego, por favor.\nVENDEDOR: Aquí tiene. Son nueve euros en total.\nANA: ¿Puedo pagar con tarjeta?\nVENDEDOR: Lo siento, solo en efectivo.\nANA: No pasa nada. Aquí tiene diez euros.", "generos": {"VENDEDOR": "masculina", "ANA": "feminina"}, "vozes": {"VENDEDOR": "Puck", "ANA": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-02-de-compras-en-el-mercado.mp3", "audio_assinatura": "ANA=Kore;VENDEDOR=Puck|VENDEDOR: ¡Buenos días! ¿Qué le pongo?\nANA: Buenos días. ¿Cuánto cuestan los tomates?\nVENDEDOR: Dos euros con cincuenta el kilo. Son muy buenos, de la huerta.\nANA: Perfecto, póngame un kilo. ¿Y las fresas?\nVENDEDOR: Las fresas cuestan cuatro euros la caja.\nANA: Mmm, me gustan mucho, pero son un poco caras. Hoy no, gracias.\nVENDEDOR: ¿Algo más?\nANA: Sí, medio kilo de queso manchego, por favor.\nVENDEDOR: Aquí tiene. Son nueve euros en total.\nANA: ¿Puedo pagar con tarjeta?\nVENDEDOR: Lo siento, solo en efectivo.\nANA: No pasa nada. Aquí tiene diez euros.", "duracao": 60.1}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('dd298abd-1530-59af-826b-db62b58dc86f', '3e7697f5-9528-510a-b1c8-1f6e414cbfaf', '78f0fe92-a24a-5813-909f-c510c5623dca', 0, 'multipla_escolha', 'listening', '¿Cuánto cuesta el kilo de tomates?', '{"opcoes": ["2,50 €", "4 €", "9 €"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('dd298abd-1530-59af-826b-db62b58dc86f', '{"correta": 0}'::jsonb, 'Dos euros con cincuenta el kilo.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('1fde2dfc-72d0-532c-922f-176f707c1d5e', '3e7697f5-9528-510a-b1c8-1f6e414cbfaf', '78f0fe92-a24a-5813-909f-c510c5623dca', 1, 'verdadeiro_falso', 'listening', 'Ana compra fresas.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('1fde2dfc-72d0-532c-922f-176f707c1d5e', '{"valor": false}'::jsonb, 'Ela gosta, mas acha caro: Hoy no, gracias.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('6c82e14b-71d6-5715-98b6-4f78876443ab', '3e7697f5-9528-510a-b1c8-1f6e414cbfaf', '78f0fe92-a24a-5813-909f-c510c5623dca', 2, 'multipla_escolha', 'listening', '¿Qué más compra Ana?', '{"opcoes": ["Pan", "Queso", "Naranjas"]}'::jsonb);
