insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('24638913-d3fe-573c-818c-dcb31567f6e1', '3e7697f5-9528-510a-b1c8-1f6e414cbfaf', '78f0fe92-a24a-5813-909f-c510c5623dca', 3, 'multipla_escolha', 'listening', '¿Cómo paga Ana?', '{"opcoes": ["Con tarjeta", "Con el móvil", "En efectivo"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('24638913-d3fe-573c-818c-dcb31567f6e1', '{"correta": 2}'::jsonb, 'O vendedor só aceita dinheiro: solo en efectivo.');
