insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('36c10283-5fd4-548b-9e3e-262114a169dd', 'Mi fin de semana', 'Pretérito indefinido', 'Conte o que você fez com o passado mais usado do espanhol.', 'espanhol', 3, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('353eb822-983b-5c26-be75-040889622c14', '36c10283-5fd4-548b-9e3e-262114a169dd', 0, 'Dica', '', 'dica', '{"texto": "O pretérito indefinido fala de ações terminadas num tempo encerrado (ayer, el sábado, el año pasado): Ayer comí paella. Atenção aos irregulares mais comuns: ir e ser → fui, fuiste, fue, fuimos; hacer → hice, hizo; tener → tuve, tuvo."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('6e47d9dd-b7da-53e0-8de9-aae9393eba7c', '36c10283-5fd4-548b-9e3e-262114a169dd', 1, 'Escucha: El lunes en la oficina', 'Ouça a conversa de segunda-feira e responda.', 'audio', '{"roteiro": "SOFÍA: ¡Hola, Diego! ¿Qué tal el fin de semana?\nDIEGO: ¡Genial! El sábado fui a Toledo con mi hermana.\nSOFÍA: ¡Qué bien! ¿Cómo fueron?\nDIEGO: En tren. Salimos muy temprano, a las siete, y llegamos en media hora.\nSOFÍA: ¿Y qué hicieron allí?\nDIEGO: Visitamos la catedral, comimos en un restaurante típico y por la tarde paseamos por el casco antiguo. ¿Y tú?\nSOFÍA: Yo no salí mucho. El sábado limpié la casa y el domingo vi una serie entera en el sofá.\nDIEGO: ¡Una serie entera! ¿Cuál?\nSOFÍA: Una de detectives. Me encantó, pero hoy tengo mucho sueño.", "generos": {"SOFÍA": "feminina", "DIEGO": "masculina"}, "vozes": {"SOFÍA": "Kore", "DIEGO": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-03-mi-fin-de-semana.mp3", "audio_assinatura": "DIEGO=Puck;SOFÍA=Kore|SOFÍA: ¡Hola, Diego! ¿Qué tal el fin de semana?\nDIEGO: ¡Genial! El sábado fui a Toledo con mi hermana.\nSOFÍA: ¡Qué bien! ¿Cómo fueron?\nDIEGO: En tren. Salimos muy temprano, a las siete, y llegamos en media hora.\nSOFÍA: ¿Y qué hicieron allí?\nDIEGO: Visitamos la catedral, comimos en un restaurante típico y por la tarde paseamos por el casco antiguo. ¿Y tú?\nSOFÍA: Yo no salí mucho. El sábado limpié la casa y el domingo vi una serie entera en el sofá.\nDIEGO: ¡Una serie entera! ¿Cuál?\nSOFÍA: Una de detectives. Me encantó, pero hoy tengo mucho sueño.", "duracao": 51.4}'::jsonb);
