insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('93c0c406-3dec-52eb-980b-bc9efe289030', 'Una entrevista de trabajo', 'Indefinido vs imperfecto', 'Conte sua trajetória profissional como uma boa história.', 'espanhol', 4, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('a05f5194-e76a-59cf-a18c-eb123c8b7b30', '93c0c406-3dec-52eb-980b-bc9efe289030', 0, 'Dica', '', 'dica', '{"texto": "O imperfecto descreve o cenário e os hábitos do passado (Trabajaba en un banco, era un equipo pequeño); o indefinido conta as ações que fazem a história andar (En 2020 cambié de empresa). Truque: se cabe a pergunta ''e aí, o que aconteceu?'', é indefinido."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('574456fa-8d09-5ea3-9743-05ccb14a3629', '93c0c406-3dec-52eb-980b-bc9efe289030', 1, 'Escucha: La entrevista', 'Ouça a entrevista e responda.', 'audio', '{"roteiro": "ELENA: Bueno, Javier, cuéntame un poco de tu experiencia.\nJAVIER: Claro. Cuando terminé la carrera, trabajé tres años en una agencia de publicidad en Bogotá. Era un equipo pequeño y hacíamos de todo: diseño, redes sociales, atención al cliente.\nELENA: ¿Y por qué decidiste cambiar?\nJAVIER: Me gustaba mucho el ambiente, pero quería especializarme en marketing digital. Así que en 2022 hice un máster en Madrid.\nELENA: ¿Y después del máster?\nJAVIER: Empecé a trabajar en una startup de turismo. Al principio era el único responsable de marketing, y el año pasado formé un equipo de cuatro personas.\nELENA: Muy interesante. ¿Cuál fue tu mayor logro allí?\nJAVIER: Lanzamos una campaña que duplicó las reservas en seis meses.", "generos": {"ELENA": "feminina", "JAVIER": "masculina"}, "vozes": {"ELENA": "Kore", "JAVIER": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-04-una-entrevista-de-trabajo.mp3", "audio_assinatura": "ELENA=Kore;JAVIER=Puck|ELENA: Bueno, Javier, cuéntame un poco de tu experiencia.\nJAVIER: Claro. Cuando terminé la carrera, trabajé tres años en una agencia de publicidad en Bogotá. Era un equipo pequeño y hacíamos de todo: diseño, redes sociales, atención al cliente.\nELENA: ¿Y por qué decidiste cambiar?\nJAVIER: Me gustaba mucho el ambiente, pero quería especializarme en marketing digital. Así que en 2022 hice un máster en Madrid.\nELENA: ¿Y después del máster?\nJAVIER: Empecé a trabajar en una startup de turismo. Al principio era el único responsable de marketing, y el año pasado formé un equipo de cuatro personas.\nELENA: Muy interesante. ¿Cuál fue tu mayor logro allí?\nJAVIER: Lanzamos una campaña que duplicó las reservas en seis meses.", "duracao": 58.9}'::jsonb);
