insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('175d01b8-ac8b-5725-a995-ffc4e2bb5233', 'En la consulta médica', 'Me duele + imperativo de usted', 'Explique o que você sente e entenda as orientações do médico.', 'espanhol', 4, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('8e985df1-561a-50e8-b7a8-54f7709085c9', '175d01b8-ac8b-5725-a995-ffc4e2bb5233', 0, 'Dica', '', 'dica', '{"texto": "Para falar de dor: Me duele la cabeza (uma parte) / Me duelen los pies (várias). Nas instruções formais (usted), o imperativo troca a vogal: verbos -ar terminam em -e (tome, descanse); verbos -er/-ir terminam em -a (beba, abra)."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('fe179e38-0566-5b70-ba15-5001e99dab21', '175d01b8-ac8b-5725-a995-ffc4e2bb5233', 1, 'Escucha: En la consulta', 'Ouça a consulta e responda.', 'audio', '{"roteiro": "DOCTORA: Buenas tardes, Pablo. ¿Qué le pasa?\nPABLO: Buenas tardes, doctora. Desde hace tres días me duele mucho la garganta y tengo un poco de fiebre.\nDOCTORA: ¿Tiene tos?\nPABLO: Sí, sobre todo por la noche. Casi no puedo dormir.\nDOCTORA: A ver, abra la boca, por favor. Sí, tiene la garganta muy inflamada. Es una faringitis.\nPABLO: ¿Es grave?\nDOCTORA: No, no se preocupe. Tome este medicamento cada ocho horas durante cinco días. Beba mucha agua y descanse.\nPABLO: ¿Puedo ir a trabajar mañana?\nDOCTORA: Mejor no. Quédese en casa dos días y, si la fiebre no baja, vuelva a la consulta.", "generos": {"DOCTORA": "feminina", "PABLO": "masculina"}, "vozes": {"DOCTORA": "Kore", "PABLO": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-05-en-la-consulta-medica.mp3", "audio_assinatura": "DOCTORA=Kore;PABLO=Puck|DOCTORA: Buenas tardes, Pablo. ¿Qué le pasa?\nPABLO: Buenas tardes, doctora. Desde hace tres días me duele mucho la garganta y tengo un poco de fiebre.\nDOCTORA: ¿Tiene tos?\nPABLO: Sí, sobre todo por la noche. Casi no puedo dormir.\nDOCTORA: A ver, abra la boca, por favor. Sí, tiene la garganta muy inflamada. Es una faringitis.\nPABLO: ¿Es grave?\nDOCTORA: No, no se preocupe. Tome este medicamento cada ocho horas durante cinco días. Beba mucha agua y descanse.\nPABLO: ¿Puedo ir a trabajar mañana?\nDOCTORA: Mejor no. Quédese en casa dos días y, si la fiebre no baja, vuelva a la consulta.", "duracao": 55.5}'::jsonb);
