insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f1a78b63-3930-510f-95a8-7705d0955278', 'f99b2b1e-dc95-5267-a8d1-e2a93fdc853d', '175d01b8-ac8b-5725-a995-ffc4e2bb5233', 3, 'lacuna', 'grammar', '(usted, descansar) ___ por lo menos ocho horas.', '{"banco": []}'::jsonb);
