insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('cb27c74b-d75d-522f-8be6-7501545c8c06', 'Viajar por Perú', 'Subjuntivo con ojalá y cuando', 'Fale de desejos e planos para a próxima viagem.', 'espanhol', 5, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('1e3ffd43-1813-5826-ad2c-250b13d481ec', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 0, 'Dica', '', 'dica', '{"texto": "Depois de ojalá, usamos subjuntivo: Ojalá haga buen tiempo. Com cuando falando do futuro, também: Cuando llegues a Cusco, llámame (nunca ''cuando llegarás''!). Para formar o presente do subjuntivo, troque a vogal: hablar → hable, comer → coma, vivir → viva."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('659cd7f6-e001-5107-b168-f969b193232c', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 1, 'Escucha: Planes para el viaje', 'Ouça a conversa e responda.', 'audio', '{"roteiro": "CAMILA: Andrés, ¿ya tienes todo listo para el viaje a Perú?\nANDRÉS: Casi. Salgo el viernes. Primero voy a pasar dos días en Lima y luego tomo un vuelo a Cusco.\nCAMILA: ¡Qué envidia! ¿Vas a hacer el Camino Inca?\nANDRÉS: No, porque no conseguí el permiso a tiempo. Pero voy a subir a Machu Picchu en tren. Ojalá no llueva mucho, porque en esta época del año es bastante común.\nCAMILA: Lleva un buen impermeable, por si acaso. Y cuando llegues a Cusco, no hagas nada el primer día. La altitud es muy fuerte.\nANDRÉS: Sí, me lo dijeron. Voy a tomar mate de coca y descansar.\nCAMILA: Perfecto. Ah, y cuando vuelvas, quiero ver todas las fotos.\nANDRÉS: ¡Claro! Ojalá tengas tiempo para un café la semana que viene.", "generos": {"CAMILA": "feminina", "ANDRÉS": "masculina"}, "vozes": {"CAMILA": "Kore", "ANDRÉS": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-06-viajar-por-peru.mp3", "audio_assinatura": "ANDRÉS=Puck;CAMILA=Kore|CAMILA: Andrés, ¿ya tienes todo listo para el viaje a Perú?\nANDRÉS: Casi. Salgo el viernes. Primero voy a pasar dos días en Lima y luego tomo un vuelo a Cusco.\nCAMILA: ¡Qué envidia! ¿Vas a hacer el Camino Inca?\nANDRÉS: No, porque no conseguí el permiso a tiempo. Pero voy a subir a Machu Picchu en tren. Ojalá no llueva mucho, porque en esta época del año es bastante común.\nCAMILA: Lleva un buen impermeable, por si acaso. Y cuando llegues a Cusco, no hagas nada el primer día. La altitud es muy fuerte.\nANDRÉS: Sí, me lo dijeron. Voy a tomar mate de coca y descansar.\nCAMILA: Perfecto. Ah, y cuando vuelvas, quiero ver todas las fotos.\nANDRÉS: ¡Claro! Ojalá tengas tiempo para un café la semana que viene.", "duracao": 58.2}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('dc7887b1-0015-58a3-80b7-d8f0598f238e', '659cd7f6-e001-5107-b168-f969b193232c', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 0, 'multipla_escolha', 'listening', '¿Cuándo sale Andrés?', '{"opcoes": ["El jueves", "El viernes", "El sábado"]}'::jsonb);
