insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('a0d505d4-2a5a-5ea7-9295-33b0bbc7956f', '659cd7f6-e001-5107-b168-f969b193232c', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 1, 'multipla_escolha', 'listening', '¿Por qué no va a hacer el Camino Inca?', '{"opcoes": ["Es muy caro", "No consiguió el permiso a tiempo", "Le da miedo la altitud"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('a0d505d4-2a5a-5ea7-9295-33b0bbc7956f', '{"correta": 1}'::jsonb, 'No conseguí el permiso a tiempo.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2219996c-56ef-5e23-b041-8c37957fd4c6', '659cd7f6-e001-5107-b168-f969b193232c', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 2, 'multipla_escolha', 'listening', '¿Cómo va a subir a Machu Picchu?', '{"opcoes": ["A pie", "En autobús", "En tren"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2219996c-56ef-5e23-b041-8c37957fd4c6', '{"correta": 2}'::jsonb, 'Voy a subir a Machu Picchu en tren.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e7e6306a-668d-533a-a824-dda2b6d32051', '659cd7f6-e001-5107-b168-f969b193232c', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 3, 'verdadeiro_falso', 'listening', 'Camila le aconseja descansar el primer día en Cusco.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e7e6306a-668d-533a-a824-dda2b6d32051', '{"valor": true}'::jsonb, 'No hagas nada el primer día; la altitud es muy fuerte.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('b6adad97-ec3d-5b6a-abcc-4274c38a8d17', '659cd7f6-e001-5107-b168-f969b193232c', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 4, 'verdadeiro_falso', 'listening', 'Andrés cree que en esta época nunca llueve.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('b6adad97-ec3d-5b6a-abcc-4274c38a8d17', '{"valor": false}'::jsonb, 'Ele diz que a chuva é bastante comum nessa época.');
