insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('4e0dc5c5-7e02-5f94-8ab7-caced785ecff', 'c9c0491e-8956-5a33-96d1-1643096783cf', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 0, 'lacuna', 'grammar', 'Ojalá ___ (hacer) sol mañana.', '{"banco": []}'::jsonb);
