insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('8892a5f1-beb9-5922-976d-8459463ddee3', 'c9c0491e-8956-5a33-96d1-1643096783cf', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 1, 'lacuna', 'grammar', 'Cuando (nosotros) ___ (terminar) el proyecto, vamos a celebrarlo.', '{"banco": []}'::jsonb);
