insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7c0ef26e-5dcb-57d2-b6bb-82e99e50ade4', 'c9c0491e-8956-5a33-96d1-1643096783cf', 'cb27c74b-d75d-522f-8be6-7501545c8c06', 2, 'lacuna_opcoes', 'grammar', 'Cuando ___ a casa, llámame.', '{"opcoes": [["llegarás", "llegues", "llegas"]]}'::jsonb);
