insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('152cd4c7-c85c-50ce-a8de-c2118950d522', 'La reunión de equipo', 'Opinar: creo que / no creo que', 'Concorde, discorde e argumente numa reunião.', 'espanhol', 5, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('99c4f692-037f-544d-8126-b46545ce9a01', '152cd4c7-c85c-50ce-a8de-c2118950d522', 0, 'Dica', '', 'dica', '{"texto": "Creo que, pienso que e me parece que vêm com indicativo (Creo que es una buena idea). Na negativa, pedem subjuntivo: No creo que sea una buena idea. Expressões de valor também pedem subjuntivo: Es importante que todos participen."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('57574dd2-938b-52da-880d-1ed4d840199d', '152cd4c7-c85c-50ce-a8de-c2118950d522', 1, 'Escucha: ¿Teletrabajo los viernes?', 'Ouça a reunião e responda.', 'audio', '{"roteiro": "LUCÍA: Bueno, el tema de hoy es la propuesta de trabajar desde casa los viernes. ¿Qué opinas, Marcos?\nMARCOS: Pues creo que es una buena idea. La mayoría del equipo pierde más de una hora al día en el transporte.\nLUCÍA: Estoy de acuerdo en eso, pero no creo que sea fácil para el equipo de atención al cliente. Ellos necesitan estar en la oficina.\nMARCOS: Es verdad. Quizás ellos puedan elegir otro día, como el lunes.\nLUCÍA: Me parece razonable. Lo que me preocupa es la comunicación. Es fundamental que todos respondan rápido a los mensajes.\nMARCOS: Podemos hacer una prueba de tres meses y medir los resultados.\nLUCÍA: Perfecto. Prepara una propuesta por escrito y la presentamos a dirección la semana que viene.", "generos": {"LUCÍA": "feminina", "MARCOS": "masculina"}, "vozes": {"LUCÍA": "Kore", "MARCOS": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-07-la-reunion-de-equipo.mp3", "audio_assinatura": "LUCÍA=Kore;MARCOS=Puck|LUCÍA: Bueno, el tema de hoy es la propuesta de trabajar desde casa los viernes. ¿Qué opinas, Marcos?\nMARCOS: Pues creo que es una buena idea. La mayoría del equipo pierde más de una hora al día en el transporte.\nLUCÍA: Estoy de acuerdo en eso, pero no creo que sea fácil para el equipo de atención al cliente. Ellos necesitan estar en la oficina.\nMARCOS: Es verdad. Quizás ellos puedan elegir otro día, como el lunes.\nLUCÍA: Me parece razonable. Lo que me preocupa es la comunicación. Es fundamental que todos respondan rápido a los mensajes.\nMARCOS: Podemos hacer una prueba de tres meses y medir los resultados.\nLUCÍA: Perfecto. Prepara una propuesta por escrito y la presentamos a dirección la semana que viene.", "duracao": 52.8}'::jsonb);
