insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('e79d982b-f800-5797-b154-d7f6ee628aa9', 'Negociar el alquiler', 'Si + imperfecto de subjuntivo', 'Negocie condições com hipóteses e cortesia.', 'espanhol', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('03d9c21f-5443-5fa8-9816-2e28111db381', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 0, 'Dica', '', 'dica', '{"texto": "Para hipóteses: Si + imperfecto de subjuntivo + condicional (Si bajara el precio, firmaría hoy). O imperfecto de subjuntivo vem da 3ª pessoa do plural do indefinido: tuvieron → tuviera, pudieron → pudiera, fueron → fuera. Nunca use condicional depois de si!"}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('ef9e4ac9-4bc6-5dae-b31a-20468d2dd1c8', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 1, 'Escucha: Hablando con el propietario', 'Ouça a negociação e responda.', 'audio', '{"roteiro": "VALERIA: Ramón, el piso me encanta, pero sinceramente el precio está un poco por encima de mi presupuesto.\nRAMÓN: Entiendo. Es una zona muy buscada, ya sabe.\nVALERIA: Lo sé. Pero si firmara un contrato de dos años en lugar de uno, ¿podría bajar el alquiler a mil cien euros?\nRAMÓN: Mil cien es demasiado poco. Si pagara tres meses por adelantado, podría dejarlo en mil ciento cincuenta.\nVALERIA: Tres meses es mucho de golpe. ¿Y si fueran dos meses y yo me encargara de pintar el salón?\nRAMÓN: Mmm. Si usted pintara el salón y además cuidara el jardín, aceptaría dos meses.\nVALERIA: Trato hecho. ¿Cuándo podríamos firmar?\nRAMÓN: Si le viene bien, el lunes por la mañana en mi oficina.", "generos": {"VALERIA": "feminina", "RAMÓN": "masculina"}, "vozes": {"VALERIA": "Kore", "RAMÓN": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-08-negociar-el-alquiler.mp3", "audio_assinatura": "RAMÓN=Puck;VALERIA=Kore|VALERIA: Ramón, el piso me encanta, pero sinceramente el precio está un poco por encima de mi presupuesto.\nRAMÓN: Entiendo. Es una zona muy buscada, ya sabe.\nVALERIA: Lo sé. Pero si firmara un contrato de dos años en lugar de uno, ¿podría bajar el alquiler a mil cien euros?\nRAMÓN: Mil cien es demasiado poco. Si pagara tres meses por adelantado, podría dejarlo en mil ciento cincuenta.\nVALERIA: Tres meses es mucho de golpe. ¿Y si fueran dos meses y yo me encargara de pintar el salón?\nRAMÓN: Mmm. Si usted pintara el salón y además cuidara el jardín, aceptaría dos meses.\nVALERIA: Trato hecho. ¿Cuándo podríamos firmar?\nRAMÓN: Si le viene bien, el lunes por la mañana en mi oficina.", "duracao": 52.7}'::jsonb);
