insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('401f0115-b3c4-56dc-8850-faee481ea473', 'ef9e4ac9-4bc6-5dae-b31a-20468d2dd1c8', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 2, 'multipla_escolha', 'listening', '¿Cuál es el precio final del alquiler?', '{"opcoes": ["1.100 €", "1.150 €", "1.200 €"]}'::jsonb);
