insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('acb9018c-5c39-538e-af1c-7b970c90aed1', 'ef9e4ac9-4bc6-5dae-b31a-20468d2dd1c8', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 3, 'verdadeiro_falso', 'listening', 'Valeria va a pintar el salón y cuidar el jardín.', '{}'::jsonb);
