insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('07c1e387-7406-5aec-ae23-d5cbfbb19fac', 'ef9e4ac9-4bc6-5dae-b31a-20468d2dd1c8', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 4, 'verdadeiro_falso', 'listening', 'Firman el contrato hoy mismo.', '{}'::jsonb);
