insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('cabd0c3a-6a92-53b0-b1ab-f469cebe0151', '986f5145-dd5d-5f6a-895c-3bd821b1f417', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 0, 'lacuna', 'grammar', 'Si ___ (yo, tener) más tiempo, aprendería a tocar la guitarra.', '{"banco": []}'::jsonb);
