insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f4ea9d1f-9435-5f33-b28d-d7b8d6b4639c', '986f5145-dd5d-5f6a-895c-3bd821b1f417', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 1, 'lacuna', 'grammar', 'Si el alquiler fuera más barato, lo ___ (alquilar) ahora mismo.', '{"banco": []}'::jsonb);
