insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('0b611622-e0e2-5c6f-9462-c61ec272c578', '986f5145-dd5d-5f6a-895c-3bd821b1f417', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 3, 'lacuna_opcoes', 'grammar', '¿Qué harías si ___ el trabajo de tus sueños en otro país?', '{"opcoes": [["consiguieras", "consigues", "conseguirías"]]}'::jsonb);
