insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('7632d459-c98a-5e68-aa31-919c305b941b', '986f5145-dd5d-5f6a-895c-3bd821b1f417', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 4, 'multipla_escolha', 'grammar', 'Elige la frase correcta:', '{"opcoes": ["Si tendría dinero, compraría la casa.", "Si tuviera dinero, compraría la casa.", "Si tuviera dinero, compraré la casa."]}'::jsonb);
