insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('3c52f574-b6c5-5455-833e-310f654b6181', '986f5145-dd5d-5f6a-895c-3bd821b1f417', 'e79d982b-f800-5797-b154-d7f6ee628aa9', 5, 'verdadeiro_falso', 'vocabulary', '"Pagar por adelantado" significa pagar antes.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('3c52f574-b6c5-5455-833e-310f654b6181', '{"valor": true}'::jsonb, 'Por adelantado = adiantado.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', '¿El fin de la oficina?', 'Conectores y estilo indirecto', 'Uma entrevista de rádio para argumentar como um falante avançado.', 'espanhol', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('fcaa353c-44f5-5700-a732-0f437d89de4f', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 0, 'Dica', '', 'dica', '{"texto": "Conectores dão força ao argumento: sin embargo e no obstante (contraste), además e asimismo (adição), por lo tanto e por consiguiente (consequência), es decir (explicação). Aunque + subjuntivo marca concessão hipotética: Aunque sea caro, vale la pena."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('fc29a7c9-6930-51f5-87c4-f9dd9b8e06c0', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 1, 'Escucha: Entrevista en la radio', 'Ouça a entrevista e responda.', 'audio', '{"roteiro": "INÉS: Buenas tardes. Hoy hablamos con Tomás Ferrer, especialista en organización del trabajo. Tomás, ¿la oficina tiene los días contados?\nTOMÁS: No lo creo. Es cierto que el teletrabajo ha llegado para quedarse; sin embargo, las empresas que eliminaron por completo la oficina han notado efectos inesperados.\nINÉS: ¿Por ejemplo?\nTOMÁS: Los empleados más jóvenes aprenden más despacio. Gran parte de lo que aprendemos en el trabajo viene de observar a los compañeros, es decir, de conversaciones informales que nadie planifica.\nINÉS: Aun así, muchos trabajadores dicen que en casa son más productivos.\nTOMÁS: Y tienen razón, sobre todo en tareas que requieren concentración. Por lo tanto, el modelo que más éxito está teniendo es el híbrido: la oficina se usa para colaborar y la casa para concentrarse.\nINÉS: ¿Y qué recomendaría a las empresas?\nTOMÁS: Que no impongan las mismas reglas para todos. Además, que pregunten a los equipos qué necesitan, aunque eso lleve más tiempo.", "generos": {"INÉS": "feminina", "TOMÁS": "masculina"}, "vozes": {"INÉS": "Kore", "TOMÁS": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-09-el-fin-de-la-oficina.mp3", "audio_assinatura": "INÉS=Kore;TOMÁS=Puck|INÉS: Buenas tardes. Hoy hablamos con Tomás Ferrer, especialista en organización del trabajo. Tomás, ¿la oficina tiene los días contados?\nTOMÁS: No lo creo. Es cierto que el teletrabajo ha llegado para quedarse; sin embargo, las empresas que eliminaron por completo la oficina han notado efectos inesperados.\nINÉS: ¿Por ejemplo?\nTOMÁS: Los empleados más jóvenes aprenden más despacio. Gran parte de lo que aprendemos en el trabajo viene de observar a los compañeros, es decir, de conversaciones informales que nadie planifica.\nINÉS: Aun así, muchos trabajadores dicen que en casa son más productivos.\nTOMÁS: Y tienen razón, sobre todo en tareas que requieren concentración. Por lo tanto, el modelo que más éxito está teniendo es el híbrido: la oficina se usa para colaborar y la casa para concentrarse.\nINÉS: ¿Y qué recomendaría a las empresas?\nTOMÁS: Que no impongan las mismas reglas para todos. Además, que pregunten a los equipos qué necesitan, aunque eso lleve más tiempo.", "duracao": 70.6}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('87ec8ca0-d71a-5a9a-869a-6a102976a2b4', 'fc29a7c9-6930-51f5-87c4-f9dd9b8e06c0', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 0, 'multipla_escolha', 'listening', '¿Qué opina Tomás sobre el futuro de la oficina?', '{"opcoes": ["Va a desaparecer pronto", "No va a desaparecer", "Es más importante que nunca"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('87ec8ca0-d71a-5a9a-869a-6a102976a2b4', '{"correta": 1}'::jsonb, 'Ele responde "No lo creo" à ideia de que a oficina tem os dias contados.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('13f7f1ed-e9c4-5435-9ef6-d3eeb8cce72f', 'fc29a7c9-6930-51f5-87c4-f9dd9b8e06c0', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 1, 'multipla_escolha', 'listening', '¿Qué efecto inesperado menciona?', '{"opcoes": ["Los empleados jóvenes aprenden más despacio", "Los gastos aumentan", "Hay más bajas por enfermedad"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('13f7f1ed-e9c4-5435-9ef6-d3eeb8cce72f', '{"correta": 0}'::jsonb, 'Los empleados más jóvenes aprenden más despacio.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('0b496814-178c-5fbf-ad5a-6805563692cf', 'fc29a7c9-6930-51f5-87c4-f9dd9b8e06c0', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 2, 'verdadeiro_falso', 'listening', 'Según Tomás, en casa se trabaja mejor en tareas de concentración.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('0b496814-178c-5fbf-ad5a-6805563692cf', '{"valor": true}'::jsonb, 'Sobre todo en tareas que requieren concentración.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('386609b5-d92d-5dd7-b98d-ae0b278208f3', 'fc29a7c9-6930-51f5-87c4-f9dd9b8e06c0', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 3, 'multipla_escolha', 'listening', '¿Qué modelo está teniendo más éxito?', '{"opcoes": ["El presencial", "El remoto", "El híbrido"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('386609b5-d92d-5dd7-b98d-ae0b278208f3', '{"correta": 2}'::jsonb, 'El modelo que más éxito está teniendo es el híbrido.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('eab6222d-db1b-5ff0-ad1b-178d27e978fc', 'fc29a7c9-6930-51f5-87c4-f9dd9b8e06c0', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 4, 'verdadeiro_falso', 'listening', 'Tomás recomienda las mismas reglas para todos los equipos.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('eab6222d-db1b-5ff0-ad1b-178d27e978fc', '{"valor": false}'::jsonb, 'Que no impongan las mismas reglas para todos.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 2, 'Conectores y estilo indirecto', 'Escolha ou complete.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('172b087f-06e9-53b2-b36b-5707c6492933', 'c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 0, 'lacuna_opcoes', 'grammar', 'El proyecto es caro; ___, es necesario.', '{"opcoes": [["además", "sin embargo", "es decir"]]}'::jsonb);
