insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c0f1741f-d531-5981-bff5-cb6599501472', 'c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 1, 'lacuna_opcoes', 'grammar', 'No llegamos a tiempo; ___, perdimos el vuelo.', '{"opcoes": [["por lo tanto", "aunque", "además"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c0f1741f-d531-5981-bff5-cb6599501472', '{"lacunas": [0]}'::jsonb, 'Consequência: por lo tanto.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('dff0d3a6-29e9-5a90-a219-475bc06ab732', 'c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 2, 'lacuna', 'grammar', '___ llueva, iremos a la excursión. (concessão: mesmo que)', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('dff0d3a6-29e9-5a90-a219-475bc06ab732', '{"lacunas": [["Aunque"]], "ignorar_acentos": false}'::jsonb, 'Aunque + subjuntivo = mesmo que.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f9e4b214-003a-5d08-99fc-3b4b8d99a386', 'c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 3, 'multipla_escolha', 'grammar', '"Pregunten a los equipos." → Tomás recomendó que...', '{"opcoes": ["...preguntan a los equipos.", "...preguntaran a los equipos.", "...preguntarán a los equipos."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('f9e4b214-003a-5d08-99fc-3b4b8d99a386', '{"correta": 1}'::jsonb, 'Verbo de influência no passado (recomendó) pede imperfecto de subjuntivo.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('ef75409e-7d50-5e27-b06d-549039e76d70', 'c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 4, 'lacuna', 'grammar', 'Tomás dijo que el teletrabajo ___ (haber) llegado para quedarse.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('ef75409e-7d50-5e27-b06d-549039e76d70', '{"lacunas": [["había"]], "ignorar_acentos": false}'::jsonb, 'No estilo indirecto, ha llegado vira había llegado.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('69a9737d-4c47-591d-a9f7-e8ae96ea1a62', 'c8b46843-2174-5605-a87b-8063576fbbea', '5ebb0d70-5ae9-524a-9ce0-40d6ccb70e64', 5, 'multipla_escolha', 'vocabulary', '"Tener los días contados" significa:', '{"opcoes": ["Estar a punto de acabar", "Tener mucho trabajo", "Contar los días de vacaciones"]}'::jsonb);
