insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 'Emprender desde cero', 'Pluscuamperfecto de subjuntivo y expresiones', 'O relato de quem arriscou tudo, para treinar o ouvido no nível avançado.', 'espanhol', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('308877d7-7128-561d-a449-54e2a29195e6', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 0, 'Dica', '', 'dica', '{"texto": "Para lamentar o que não aconteceu: Si + pluscuamperfecto de subjuntivo + condicional compuesto (Si hubiera hablado con mis clientes, me habría ahorrado mucho dinero). Com ojalá, o mesmo tempo expressa um desejo impossível sobre o passado: Ojalá hubiera aceptado."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('7b8d026a-1813-578d-867a-3721290a9901', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 1, 'Escucha: Una historia de emprendimiento', 'Ouça o relato de Valentina e responda.', 'audio', '{"roteiro": "VALENTINA: Hace cinco años dejé un puesto estable en un banco de Santiago para montar una empresa de cosmética natural. Mucha gente me dijo que estaba loca, y, la verdad, al principio no les faltaba razón.\nVALENTINA: El primer año fue un desastre. Invertí casi todos mis ahorros en un producto que nadie quería comprar. Si hubiera hablado antes con mis clientes, me habría ahorrado mucho dinero y muchos disgustos.\nVALENTINA: Lo que me salvó fue escuchar. Empecé a hacer pequeñas encuestas en las ferias y descubrí que lo que la gente buscaba no era un champú de lujo, sino algo práctico y barato para viajar.\nVALENTINA: Cambiamos el producto, bajamos los precios y, en menos de un año, empezamos a vender en Perú y en Colombia. Hoy somos doce personas.\nVALENTINA: Si tuviera que dar un solo consejo, sería este: no te enamores de tu idea, enamórate del problema que resuelves. Y no tengas miedo de equivocarte, porque de los errores se aprende más que de los aciertos.", "generos": {"VALENTINA": "feminina"}, "vozes": {"VALENTINA": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-espanhol-10-emprender-desde-cero.mp3", "audio_assinatura": "VALENTINA=Kore|VALENTINA: Hace cinco años dejé un puesto estable en un banco de Santiago para montar una empresa de cosmética natural. Mucha gente me dijo que estaba loca, y, la verdad, al principio no les faltaba razón.\nVALENTINA: El primer año fue un desastre. Invertí casi todos mis ahorros en un producto que nadie quería comprar. Si hubiera hablado antes con mis clientes, me habría ahorrado mucho dinero y muchos disgustos.\nVALENTINA: Lo que me salvó fue escuchar. Empecé a hacer pequeñas encuestas en las ferias y descubrí que lo que la gente buscaba no era un champú de lujo, sino algo práctico y barato para viajar.\nVALENTINA: Cambiamos el producto, bajamos los precios y, en menos de un año, empezamos a vender en Perú y en Colombia. Hoy somos doce personas.\nVALENTINA: Si tuviera que dar un solo consejo, sería este: no te enamores de tu idea, enamórate del problema que resuelves. Y no tengas miedo de equivocarte, porque de los errores se aprende más que de los aciertos.", "duracao": 64.2}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('5f068198-e0f1-528c-8be9-d683516ed3b0', '7b8d026a-1813-578d-867a-3721290a9901', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 0, 'multipla_escolha', 'listening', '¿Dónde trabajaba Valentina antes?', '{"opcoes": ["En una empresa de cosmética", "En un banco", "En una feria"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('5f068198-e0f1-528c-8be9-d683516ed3b0', '{"correta": 1}'::jsonb, 'Dejé un puesto estable en un banco de Santiago.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('4f490bf6-63fa-59f3-95e6-2cc1cea93ede', '7b8d026a-1813-578d-867a-3721290a9901', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 1, 'verdadeiro_falso', 'listening', 'El primer año de la empresa fue un éxito.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('4f490bf6-63fa-59f3-95e6-2cc1cea93ede', '{"valor": false}'::jsonb, 'El primer año fue un desastre.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('90499e90-7513-5581-8709-9a4ccbb456b0', '7b8d026a-1813-578d-867a-3721290a9901', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 2, 'multipla_escolha', 'listening', '¿Qué descubrió con las encuestas?', '{"opcoes": ["Que la gente quería un champú de lujo", "Que la gente buscaba algo práctico y barato para viajar", "Que sus precios eran bajos"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('90499e90-7513-5581-8709-9a4ccbb456b0', '{"correta": 1}'::jsonb, 'Algo práctico y barato para viajar.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('f674b02d-0a05-5588-9898-516e7581f6a8', '7b8d026a-1813-578d-867a-3721290a9901', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 3, 'multipla_escolha', 'listening', '¿Cuántas personas trabajan hoy en la empresa?', '{"opcoes": ["Cinco", "Doce", "Veinte"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('f674b02d-0a05-5588-9898-516e7581f6a8', '{"correta": 1}'::jsonb, 'Hoy somos doce personas.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('54994b2b-cd06-54bd-8711-a0e60a21f5a4', '7b8d026a-1813-578d-867a-3721290a9901', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 4, 'multipla_escolha', 'listening', '¿Cuál es su principal consejo?', '{"opcoes": ["Invertir todos los ahorros", "Enamorarse del problema, no de la idea", "No escuchar a los demás"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('54994b2b-cd06-54bd-8711-a0e60a21f5a4', '{"correta": 1}'::jsonb, 'No te enamores de tu idea, enamórate del problema que resuelves.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('e3e3c454-fc5f-56ef-85dd-c38ba4425a72', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 2, 'Lamentos y expresiones', 'Complete ou escolha o significado.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('585cb9e2-9da1-52b7-a4c6-27390315a3ed', 'e3e3c454-fc5f-56ef-85dd-c38ba4425a72', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 0, 'lacuna', 'grammar', 'Si (yo) ___ (saber) la verdad, no habría firmado el contrato.', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('585cb9e2-9da1-52b7-a4c6-27390315a3ed', '{"lacunas": [["hubiera sabido", "hubiese sabido"]], "ignorar_acentos": false}'::jsonb, 'Si + pluscuamperfecto de subjuntivo: hubiera sabido.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('40a6e520-76d2-559b-bbef-3843ea19bda7', 'e3e3c454-fc5f-56ef-85dd-c38ba4425a72', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 1, 'lacuna', 'grammar', 'Si hubiéramos salido antes, no ___ (perder) el tren.', '{"banco": []}'::jsonb);
