insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2bf4bde9-6f1f-5c4c-9ce2-043e7e01ab9b', 'e3e3c454-fc5f-56ef-85dd-c38ba4425a72', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 2, 'lacuna_opcoes', 'grammar', 'Ojalá ___ aceptado aquella oferta el año pasado.', '{"opcoes": [["hubiera", "habría", "haya"]]}'::jsonb);
