insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('aff51d3b-869c-5862-9742-979841530e5d', 'e3e3c454-fc5f-56ef-85dd-c38ba4425a72', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 3, 'multipla_escolha', 'vocabulary', '"No les faltaba razón" significa:', '{"opcoes": ["Eles tinham razão.", "Eles não tinham razão.", "Eles estavam com raiva."]}'::jsonb);
