insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('22766fde-62da-58c2-8a39-3e3197fa55a9', 'e3e3c454-fc5f-56ef-85dd-c38ba4425a72', '6c43a7df-15e1-5a19-a9b2-c2aa047e6db5', 4, 'multipla_escolha', 'vocabulary', '"Montar una empresa" significa:', '{"opcoes": ["Vender uma empresa", "Abrir uma empresa", "Fechar uma empresa"]}'::jsonb);
