insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('65858bd9-044f-52d7-9a11-732b2981f717', 'Enchanté !', 'Se présenter : être et s''appeler', 'Seus primeiros minutos falando francês.', 'frances', 1, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('6951dc03-eeb8-5155-be39-f89575a7cf96', '65858bd9-044f-52d7-9a11-732b2981f717', 0, 'Dica', '', 'dica', '{"texto": "Être: je suis, tu es, il/elle est, nous sommes, vous êtes, ils/elles sont. Para dizer o nome: Je m''appelle Ana. Use vous com quem você não conhece ou no trabalho, e tu com amigos e família."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('b85078a7-98d1-551c-b26b-975334cbf19d', '65858bd9-044f-52d7-9a11-732b2981f717', 1, 'Écoute : À l''école de langues', 'Ouça o diálogo e responda.', 'audio', '{"roteiro": "CLAIRE: Bonjour ! Vous êtes nouveau ici ?\nTHIAGO: Oui, bonjour. Je m''appelle Thiago. Et vous ?\nCLAIRE: Je m''appelle Claire. Je suis la professeure de français. Enchantée !\nTHIAGO: Enchanté, Claire.\nCLAIRE: Vous êtes d''où, Thiago ?\nTHIAGO: Je suis brésilien, de Recife. Je suis architecte.\nCLAIRE: Très bien ! Et vous habitez à Lyon ?\nTHIAGO: Oui, j''habite à Lyon depuis un mois.\nCLAIRE: Parfait. Le cours commence à neuf heures, dans la salle quatre.", "generos": {"CLAIRE": "feminina", "THIAGO": "masculina"}, "vozes": {"CLAIRE": "Kore", "THIAGO": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-frances-01-enchante.mp3", "audio_assinatura": "CLAIRE=Kore;THIAGO=Puck|CLAIRE: Bonjour ! Vous êtes nouveau ici ?\nTHIAGO: Oui, bonjour. Je m''appelle Thiago. Et vous ?\nCLAIRE: Je m''appelle Claire. Je suis la professeure de français. Enchantée !\nTHIAGO: Enchanté, Claire.\nCLAIRE: Vous êtes d''où, Thiago ?\nTHIAGO: Je suis brésilien, de Recife. Je suis architecte.\nCLAIRE: Très bien ! Et vous habitez à Lyon ?\nTHIAGO: Oui, j''habite à Lyon depuis un mois.\nCLAIRE: Parfait. Le cours commence à neuf heures, dans la salle quatre.", "duracao": 47.0}'::jsonb);
