insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('05231bc3-791c-52f0-99f5-149f37f8cce3', '50a48e8a-cbbf-5624-8459-daa2acc98d8d', '65858bd9-044f-52d7-9a11-732b2981f717', 4, 'multipla_escolha', 'vocabulary', 'Com quem usamos "vous"?', '{"opcoes": ["Com um amigo próximo", "Com uma pessoa que não conhecemos", "Com um irmão"]}'::jsonb);
