insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('d589592f-1774-5558-a88b-87f2ee810560', 'Un week-end à Bordeaux', 'Passé composé avec être et avoir', 'Conte sua viagem no passado sem errar o auxiliar.', 'frances', 3, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('49b34fa6-5707-559f-9966-200ee8df1f54', 'd589592f-1774-5558-a88b-87f2ee810560', 0, 'Dica', '', 'dica', '{"texto": "A maioria dos verbos usa avoir no passé composé (j''ai visité, nous avons mangé). Verbos de movimento e de mudança de estado usam être, e o particípio concorda com o sujeito: elle est allée, ils sont partis. Pense na ''maison d''être'': aller, venir, partir, arriver, entrer, sortir, rester..."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('3aed5132-680c-564b-b667-ee69c8594fcc', 'd589592f-1774-5558-a88b-87f2ee810560', 1, 'Écoute : Lundi matin au bureau', 'Ouça a conversa e responda.', 'audio', '{"roteiro": "JULIE: Salut Marc ! Tu as passé un bon week-end ?\nMARC: Excellent ! Je suis allé à Bordeaux avec ma femme.\nJULIE: Super ! Vous êtes partis quand ?\nMARC: Vendredi soir, en train. Nous sommes arrivés vers vingt-deux heures.\nJULIE: Et qu''est-ce que vous avez fait ?\nMARC: Samedi, nous avons visité des vignobles et nous avons goûté beaucoup de vins. Le soir, on a dîné au bord de la Garonne.\nJULIE: Ça a l''air génial. Et dimanche ?\nMARC: Dimanche, il a plu toute la journée, alors nous sommes restés à l''hôtel et nous avons lu. Et toi ?\nJULIE: Moi, je n''ai rien fait de spécial. J''ai fini un rapport pour le travail.", "generos": {"JULIE": "feminina", "MARC": "masculina"}, "vozes": {"JULIE": "Kore", "MARC": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-frances-02-un-week-end-a-bordeaux.mp3", "audio_assinatura": "JULIE=Kore;MARC=Puck|JULIE: Salut Marc ! Tu as passé un bon week-end ?\nMARC: Excellent ! Je suis allé à Bordeaux avec ma femme.\nJULIE: Super ! Vous êtes partis quand ?\nMARC: Vendredi soir, en train. Nous sommes arrivés vers vingt-deux heures.\nJULIE: Et qu''est-ce que vous avez fait ?\nMARC: Samedi, nous avons visité des vignobles et nous avons goûté beaucoup de vins. Le soir, on a dîné au bord de la Garonne.\nJULIE: Ça a l''air génial. Et dimanche ?\nMARC: Dimanche, il a plu toute la journée, alors nous sommes restés à l''hôtel et nous avons lu. Et toi ?\nJULIE: Moi, je n''ai rien fait de spécial. J''ai fini un rapport pour le travail.", "duracao": 51.4}'::jsonb);
