insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('ee4c05ae-27a2-5d00-aee5-cc5ccb31cc94', '3aed5132-680c-564b-b667-ee69c8594fcc', 'd589592f-1774-5558-a88b-87f2ee810560', 3, 'multipla_escolha', 'listening', 'Qu''est-ce qu''ils ont fait dimanche ?', '{"opcoes": ["Ils ont visité des vignobles", "Ils sont restés à l''hôtel", "Ils sont rentrés à Paris"]}'::jsonb);
