insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('53266863-5e30-585c-82ab-2772f7b6f3f7', '3aed5132-680c-564b-b667-ee69c8594fcc', 'd589592f-1774-5558-a88b-87f2ee810560', 4, 'verdadeiro_falso', 'listening', 'Julie a passé un week-end très spécial.', '{}'::jsonb);
