insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('690f6051-bbf0-5cb7-a69b-bbf57b3656f2', 'd63e2ec0-4289-545f-b6a6-93337cd5390b', 'd589592f-1774-5558-a88b-87f2ee810560', 2, 'lacuna', 'grammar', 'Ils sont ___ (partir) à huit heures.', '{"banco": []}'::jsonb);
