insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('bb1bcb93-319e-5ba6-b10a-e71c091ad8b3', 'Préparer la réunion', 'Pronoms COD et COI', 'Evite repetições e soe natural no trabalho.', 'frances', 4, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('7f1c8f03-e7e4-5b3c-8aa0-2ae9cee20c2d', 'bb1bcb93-319e-5ba6-b10a-e71c091ad8b3', 0, 'Dica', '', 'dica', '{"texto": "O COD substitui o objeto direto: le, la, les (Je lis le rapport → Je le lis). O COI substitui a pessoa depois de à: lui, leur (Je parle au client → Je lui parle). O pronome vem antes do verbo; no passé composé, antes do auxiliar: Je l''ai envoyé."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('3f07d945-18af-518a-8531-214940165a57', 'bb1bcb93-319e-5ba6-b10a-e71c091ad8b3', 1, 'Écoute : Avant la réunion', 'Ouça a conversa e responda.', 'audio', '{"roteiro": "SOPHIE: Karim, tu as envoyé la présentation au client ?\nKARIM: Oui, je la lui ai envoyée hier soir. Mais il ne m''a pas encore répondu.\nSOPHIE: D''accord. Et les chiffres du trimestre, tu les as vérifiés ?\nKARIM: Je les ai vérifiés ce matin, mais il manque les ventes de l''Espagne.\nSOPHIE: Ah, c''est Laura qui les a. Tu peux lui téléphoner ?\nKARIM: Je lui ai déjà écrit un e-mail. Je vais l''appeler tout de suite.\nSOPHIE: Parfait. La réunion commence à quatorze heures. N''oublie pas l''ordinateur portable.\nKARIM: Je vais l''apporter, ne t''inquiète pas. Et le directeur, on l''invite aussi ?\nSOPHIE: Oui, invite-le. Il veut connaître le nouveau projet.", "generos": {"SOPHIE": "feminina", "KARIM": "masculina"}, "vozes": {"SOPHIE": "Kore", "KARIM": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-frances-03-preparer-la-reunion.mp3", "audio_assinatura": "KARIM=Puck;SOPHIE=Kore|SOPHIE: Karim, tu as envoyé la présentation au client ?\nKARIM: Oui, je la lui ai envoyée hier soir. Mais il ne m''a pas encore répondu.\nSOPHIE: D''accord. Et les chiffres du trimestre, tu les as vérifiés ?\nKARIM: Je les ai vérifiés ce matin, mais il manque les ventes de l''Espagne.\nSOPHIE: Ah, c''est Laura qui les a. Tu peux lui téléphoner ?\nKARIM: Je lui ai déjà écrit un e-mail. Je vais l''appeler tout de suite.\nSOPHIE: Parfait. La réunion commence à quatorze heures. N''oublie pas l''ordinateur portable.\nKARIM: Je vais l''apporter, ne t''inquiète pas. Et le directeur, on l''invite aussi ?\nSOPHIE: Oui, invite-le. Il veut connaître le nouveau projet.", "duracao": 53.3}'::jsonb);
