insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('af360a0b-2787-5eb4-9ffe-b50411da880e', 'Chercher un appartement à Paris', 'Subjonctif et conditionnel', 'Necessidades, pedidos e hipóteses na busca por moradia.', 'frances', 5, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('45d134aa-7474-5839-8bde-56f6c6319920', 'af360a0b-2787-5eb4-9ffe-b50411da880e', 0, 'Dica', '', 'dica', '{"texto": "Il faut que, je voudrais que e bien que pedem subjonctif: Il faut que vous soyez rapide. Para pedidos educados e hipóteses, use o conditionnel: Je voudrais visiter l''appartement; Si j''avais un garant, ce serait plus facile."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('749f4b57-5af2-576b-8743-0474e6180246', 'af360a0b-2787-5eb4-9ffe-b50411da880e', 1, 'Écoute : À l''agence immobilière', 'Ouça a conversa na imobiliária e responda.', 'audio', '{"roteiro": "INÈS: Bonjour, je cherche un deux-pièces dans le onzième arrondissement, pas trop loin du métro.\nDUBOIS: Bonjour. Quel est votre budget ?\nINÈS: Je voudrais ne pas dépasser mille deux cents euros par mois, charges comprises.\nDUBOIS: C''est possible, mais il faut que vous soyez rapide. Les appartements partent en quelques jours.\nINÈS: Quels documents faut-il que je fournisse ?\nDUBOIS: Il faut que vous nous donniez vos trois dernières fiches de paie et une pièce d''identité. Et il faudrait aussi un garant.\nINÈS: Un garant ? Je viens d''arriver en France, je ne connais personne ici.\nDUBOIS: Dans ce cas, vous pourriez utiliser une garantie en ligne. Ça coûte environ trois pour cent du loyer annuel.\nINÈS: D''accord. Bien que ce soit un peu cher, je préfère cette solution. Est-ce qu''on pourrait visiter un appartement cette semaine ?\nDUBOIS: J''en ai un rue Oberkampf. Je vous propose jeudi à dix-huit heures.", "generos": {"INÈS": "feminina", "DUBOIS": "masculina"}, "vozes": {"INÈS": "Kore", "DUBOIS": "Puck"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-frances-04-chercher-un-appartement-a-paris.mp3", "audio_assinatura": "DUBOIS=Puck;INÈS=Kore|INÈS: Bonjour, je cherche un deux-pièces dans le onzième arrondissement, pas trop loin du métro.\nDUBOIS: Bonjour. Quel est votre budget ?\nINÈS: Je voudrais ne pas dépasser mille deux cents euros par mois, charges comprises.\nDUBOIS: C''est possible, mais il faut que vous soyez rapide. Les appartements partent en quelques jours.\nINÈS: Quels documents faut-il que je fournisse ?\nDUBOIS: Il faut que vous nous donniez vos trois dernières fiches de paie et une pièce d''identité. Et il faudrait aussi un garant.\nINÈS: Un garant ? Je viens d''arriver en France, je ne connais personne ici.\nDUBOIS: Dans ce cas, vous pourriez utiliser une garantie en ligne. Ça coûte environ trois pour cent du loyer annuel.\nINÈS: D''accord. Bien que ce soit un peu cher, je préfère cette solution. Est-ce qu''on pourrait visiter un appartement cette semaine ?\nDUBOIS: J''en ai un rue Oberkampf. Je vous propose jeudi à dix-huit heures.", "duracao": 62.3}'::jsonb);
