insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('5a3c3743-a09f-59ff-b7f1-443f4445421e', '749f4b57-5af2-576b-8743-0474e6180246', 'af360a0b-2787-5eb4-9ffe-b50411da880e', 3, 'multipla_escolha', 'listening', 'Pourquoi Inès n''a-t-elle pas de garant ?', '{"opcoes": ["Elle n''a pas de travail", "Elle vient d''arriver en France", "Ses parents refusent"]}'::jsonb);
