insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('bea098ab-a557-579f-8480-99183efa788a', 'be771c63-a528-59e8-aca9-fbd75164e11d', 'af360a0b-2787-5eb4-9ffe-b50411da880e', 3, 'lacuna_opcoes', 'grammar', 'Si j''avais plus d''argent, j''___ un plus grand appartement.', '{"opcoes": [["achète", "achèterais", "achèterai"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('bea098ab-a557-579f-8480-99183efa788a', '{"lacunas": [1]}'::jsonb, 'Si + imparfait → conditionnel: achèterais.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('065ba9a5-df91-5a98-96c1-147108bdcf87', 'be771c63-a528-59e8-aca9-fbd75164e11d', 'af360a0b-2787-5eb4-9ffe-b50411da880e', 4, 'multipla_escolha', 'vocabulary', 'Qual é a forma mais educada?', '{"opcoes": ["Je veux visiter l''appartement.", "Je voudrais visiter l''appartement.", "Visitez l''appartement."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('065ba9a5-df91-5a98-96c1-147108bdcf87', '{"correta": 1}'::jsonb, 'O conditionnel (je voudrais) suaviza o pedido.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('d583674d-0e1e-59e0-81b9-633474f3c201', 'be771c63-a528-59e8-aca9-fbd75164e11d', 'af360a0b-2787-5eb4-9ffe-b50411da880e', 5, 'verdadeiro_falso', 'vocabulary', '"Charges comprises" significa que as despesas do prédio estão incluídas.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('d583674d-0e1e-59e0-81b9-633474f3c201', '{"valor": true}'::jsonb, 'Charges = despesas de condomínio; comprises = incluídas.');
insert into public.listas (id, titulo, tema, descricao, idioma, nivel, status, origem, criado_por) values ('83973e49-4f33-5a82-ae09-3a97d9597370', 'La ville du quart d''heure', 'Connecteurs logiques et conditionnel passé', 'Uma entrevista de rádio para treinar o francês avançado.', 'frances', 6, 'publicada', 'exemplo', (select id from public.perfis where papel = 'admin' order by criado_em limit 1));
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('9f25cd0c-ed0d-5d76-957f-317a568af7b5', '83973e49-4f33-5a82-ae09-3a97d9597370', 0, 'Dica', '', 'dica', '{"texto": "Conectores: cependant e pourtant (contraste), en effet (confirma e explica), donc e par conséquent (consequência), d''ailleurs (acrescenta um argumento). O conditionnel passé fala do que não aconteceu: On aurait dû consulter les habitants (deveríamos ter consultado)."}'::jsonb);
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('08545b8b-d695-5700-a4b6-2db498da6362', '83973e49-4f33-5a82-ae09-3a97d9597370', 1, 'Écoute : Entretien à la radio', 'Ouça a entrevista e responda.', 'audio', '{"roteiro": "ANTOINE: Bonjour Nadia. Vous êtes urbaniste et vous défendez l''idée de la ville du quart d''heure. De quoi s''agit-il exactement ?\nNADIA: C''est une ville où l''on trouve l''essentiel à moins de quinze minutes à pied ou à vélo : le travail, les écoles, les commerces, les soins médicaux. L''objectif, c''est de réduire les déplacements en voiture.\nANTOINE: Cependant, beaucoup de gens craignent que ce modèle limite leur liberté de circuler.\nNADIA: C''est une crainte compréhensible, mais il ne s''agit pas d''interdire quoi que ce soit. Il s''agit plutôt de rendre les longs trajets facultatifs.\nANTOINE: Et quelles erreurs avez-vous observées dans les villes qui ont essayé ?\nNADIA: La principale, c''est d''avoir imposé les changements trop vite. Dans certains quartiers, on aurait dû consulter les habitants avant de fermer des rues à la circulation. Par conséquent, des projets intéressants ont été rejetés.\nANTOINE: Et si vous deviez convaincre un maire sceptique ?\nNADIA: Je lui dirais de commencer petit : une rue piétonne près d''une école, par exemple. D''ailleurs, ce sont souvent les parents qui deviennent les meilleurs défenseurs du projet.", "generos": {"ANTOINE": "masculina", "NADIA": "feminina"}, "vozes": {"ANTOINE": "Puck", "NADIA": "Kore"}, "transcricao": "depois", "audio_url": "https://txzjjmufcevisnsvtjwt.supabase.co/storage/v1/object/public/audios/exemplo-frances-05-la-ville-du-quart-d-heure.mp3", "audio_assinatura": "ANTOINE=Puck;NADIA=Kore|ANTOINE: Bonjour Nadia. Vous êtes urbaniste et vous défendez l''idée de la ville du quart d''heure. De quoi s''agit-il exactement ?\nNADIA: C''est une ville où l''on trouve l''essentiel à moins de quinze minutes à pied ou à vélo : le travail, les écoles, les commerces, les soins médicaux. L''objectif, c''est de réduire les déplacements en voiture.\nANTOINE: Cependant, beaucoup de gens craignent que ce modèle limite leur liberté de circuler.\nNADIA: C''est une crainte compréhensible, mais il ne s''agit pas d''interdire quoi que ce soit. Il s''agit plutôt de rendre les longs trajets facultatifs.\nANTOINE: Et quelles erreurs avez-vous observées dans les villes qui ont essayé ?\nNADIA: La principale, c''est d''avoir imposé les changements trop vite. Dans certains quartiers, on aurait dû consulter les habitants avant de fermer des rues à la circulation. Par conséquent, des projets intéressants ont été rejetés.\nANTOINE: Et si vous deviez convaincre un maire sceptique ?\nNADIA: Je lui dirais de commencer petit : une rue piétonne près d''une école, par exemple. D''ailleurs, ce sont souvent les parents qui deviennent les meilleurs défenseurs du projet.", "duracao": 71.0}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('c28aec5c-20ec-5f55-9d32-c44bbf707879', '08545b8b-d695-5700-a4b6-2db498da6362', '83973e49-4f33-5a82-ae09-3a97d9597370', 0, 'multipla_escolha', 'listening', 'Qu''est-ce que la ville du quart d''heure ?', '{"opcoes": ["Une ville où tout ferme à quinze heures", "Une ville où l''essentiel est à moins de quinze minutes", "Une ville sans voitures"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('c28aec5c-20ec-5f55-9d32-c44bbf707879', '{"correta": 1}'::jsonb, 'L''essentiel à moins de quinze minutes à pied ou à vélo.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('405f13f3-f945-5573-b834-1b48c967f3c4', '08545b8b-d695-5700-a4b6-2db498da6362', '83973e49-4f33-5a82-ae09-3a97d9597370', 1, 'verdadeiro_falso', 'listening', 'Selon Nadia, le modèle interdit les longs trajets.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('405f13f3-f945-5573-b834-1b48c967f3c4', '{"valor": false}'::jsonb, 'Il ne s''agit pas d''interdire; os trajetos longos ficam opcionais.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('55e3ddaf-8b42-53ff-b84c-a804eab13173', '08545b8b-d695-5700-a4b6-2db498da6362', '83973e49-4f33-5a82-ae09-3a97d9597370', 2, 'multipla_escolha', 'listening', 'Quelle a été la principale erreur ?', '{"opcoes": ["Construire trop d''écoles", "Imposer les changements trop vite", "Manquer d''argent"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('55e3ddaf-8b42-53ff-b84c-a804eab13173', '{"correta": 1}'::jsonb, 'D''avoir imposé les changements trop vite.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('25bcff0a-af6d-548b-8ccc-f8eac17b9439', '08545b8b-d695-5700-a4b6-2db498da6362', '83973e49-4f33-5a82-ae09-3a97d9597370', 3, 'multipla_escolha', 'listening', 'Que conseille-t-elle à un maire sceptique ?', '{"opcoes": ["Fermer tout le centre-ville", "Commencer petit", "Attendre quelques années"]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('25bcff0a-af6d-548b-8ccc-f8eac17b9439', '{"correta": 1}'::jsonb, 'Je lui dirais de commencer petit.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('2dc8819b-dfd2-534a-a52e-d9c648a7570b', '08545b8b-d695-5700-a4b6-2db498da6362', '83973e49-4f33-5a82-ae09-3a97d9597370', 4, 'verdadeiro_falso', 'listening', 'Selon Nadia, les parents deviennent souvent les défenseurs du projet.', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('2dc8819b-dfd2-534a-a52e-d9c648a7570b', '{"valor": true}'::jsonb, 'Ce sont souvent les parents qui deviennent les meilleurs défenseurs du projet.');
insert into public.secoes (id, lista_id, ordem, titulo, instrucao, tipo_estimulo, estimulo) values ('8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 2, 'Connecteurs et conditionnel passé', 'Escolha ou complete.', 'nenhum', '{}'::jsonb);
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('fb5e6b23-ac3a-5d05-98dc-a8245b6f70e6', '8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 0, 'lacuna_opcoes', 'grammar', 'Le projet était coûteux ; ___, il a été approuvé.', '{"opcoes": [["pourtant", "donc", "en effet"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('fb5e6b23-ac3a-5d05-98dc-a8245b6f70e6', '{"lacunas": [0]}'::jsonb, 'Contraste: pourtant.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('74919fe7-b133-5a43-88b3-20c9611b0bd0', '8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 1, 'lacuna_opcoes', 'grammar', 'Les rues sont fermées aux voitures ; ___, il y a moins de pollution.', '{"opcoes": [["cependant", "par conséquent", "pourtant"]]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('74919fe7-b133-5a43-88b3-20c9611b0bd0', '{"lacunas": [1]}'::jsonb, 'Consequência: par conséquent.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('707f76a2-4dfb-5520-b35b-5cd84d1bb158', '8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 2, 'lacuna', 'grammar', 'Nous ___ dû partir plus tôt. (avoir, conditionnel)', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('707f76a2-4dfb-5520-b35b-5cd84d1bb158', '{"lacunas": [["aurions"]], "ignorar_acentos": false}'::jsonb, 'Conditionnel de avoir com nous: aurions (aurions dû = deveríamos ter).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('26c19d05-a4ed-5100-a26b-5e433a3b059d', '8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 3, 'lacuna', 'grammar', 'Si j''avais su, je ne ___ pas ___ (venir).', '{"banco": []}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('26c19d05-a4ed-5100-a26b-5e433a3b059d', '{"lacunas": [["serais"], ["venu", "venue"]], "ignorar_acentos": false}'::jsonb, 'Conditionnel passé com être: je ne serais pas venu(e).');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('1388acbd-8e1b-58f0-8d29-0b83d79301fc', '8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 4, 'multipla_escolha', 'vocabulary', '« Il ne s''agit pas d''interdire » signifie :', '{"opcoes": ["Não se trata de proibir.", "Não se deve proibir.", "Não é possível proibir."]}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('1388acbd-8e1b-58f0-8d29-0b83d79301fc', '{"correta": 0}'::jsonb, 'Il s''agit de = trata-se de.');
insert into public.questoes (id, secao_id, lista_id, ordem, formato, habilidade, enunciado, conteudo) values ('e4b667dd-2646-5ab9-8f72-6817f708bebe', '8a31e3a5-24b7-5090-b2a5-89bfa6ab98d5', '83973e49-4f33-5a82-ae09-3a97d9597370', 5, 'verdadeiro_falso', 'vocabulary', '« Craindre » signifie « temer, ter receio ».', '{}'::jsonb);
insert into public.gabaritos (questao_id, gabarito, explicacao) values ('e4b667dd-2646-5ab9-8f72-6817f708bebe', '{"valor": true}'::jsonb, 'Craindre = temer; une crainte = um receio.');
